INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l82','be covered in dust','',NULL,'/bi ˈkʌvərd ɪn dʌst/','It was covered in dust.','它落满了灰尘。','The old books were covered in dust.','那些旧书上积满了灰尘。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l82','laugh at','',NULL,'/læf æt/','At first the family laughed at it.','起初一家人还嘲笑它。','Don''t laugh at other people''s mistakes.','别嘲笑别人的错误。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l82','go on display','',NULL,'/ɡoʊ ɑːn dɪˈspleɪ/','The object will go on display next month.','这件物品下个月将展出。','The paintings go on display tomorrow.','这些画明天开始展出。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l82','for the first time','',NULL,'/fɔːr ðə fɜːrst taɪm/','It will be shown for the first time.','它将第一次被展出。','She saw the sea for the first time.','她第一次看到大海。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp1','choice','{"stem":"\"Last week, a strange old object ___ in the attic.\"(被发现:一般过去被动)","options":["was finding","has found","found","was found"],"answer_index":3,"stem_cn":"上周,在阁楼里发现了一件古怪的旧物。","explanation_cn":"过去“被发现”,用一般过去的被动 was + 过去分词。✓ a strange old object was found in the attic. ✗ found:主动,意思成了“物品发现了”;✗ was finding:进行主动;✗ has found:现在完成主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp1','choice','{"stem":"\"It ___ in dust and looked like junk.\"(被覆盖:一般过去被动)","options":["was covered","was covering","covered","has covered"],"answer_index":0,"stem_cn":"它落满灰尘,看着像废物。","explanation_cn":"过去“被(灰尘)覆盖”,用一般过去的被动。✓ It was covered in dust. ✗ covered:主动;✗ was covering:进行主动;✗ has covered:现在完成主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp1','choice','{"stem":"\"When it ___, a curious pattern appeared.\"(被清理:一般过去被动)","options":["has cleaned","was cleaning","was cleaned","cleaned"],"answer_index":2,"stem_cn":"把它清理干净后,出现了一个奇特的图案。","explanation_cn":"过去“被清理”,用一般过去的被动。✓ When it was cleaned, a pattern appeared. ✗ cleaned:主动;✗ was cleaning:进行主动;✗ has cleaned:现在完成主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp2','choice','{"stem":"\"Now the object ___ by experts at the museum.\"(正在被鉴定:现在进行被动)","options":["examines","is being examined","is examined","is examining"],"answer_index":1,"stem_cn":"现在这件物品正由博物馆的专家们鉴定。","explanation_cn":"此刻“正在被鉴定”,用现在进行的被动 is being + 过去分词。✓ the object is being examined by experts. ✗ is examined:一般现在被动,不表“正在”;✗ is examining:进行主动;✗ examines:一般现在主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp2','choice','{"stem":"\"Right now a full report ___ written about it.\"(正在被写:现在进行被动)","options":["is being","has been","is","was"],"answer_index":0,"stem_cn":"此刻正在写一份关于它的完整报告。","explanation_cn":"此刻“正在被写”,用现在进行被动 is being + 过去分词。✓ a full report is being written about it. ✗ is:构不成进行被动;✗ has been:现在完成被动;✗ was:过去。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp2','choice','{"stem":"\"Look — the old shelf ___ repaired at the moment.\"(正在被修:现在进行被动)","options":["is","is being","will be","has been"],"answer_index":1,"stem_cn":"看——那个旧架子此刻正在维修。","explanation_cn":"此刻“正在被修”,用现在进行被动。✓ the old shelf is being repaired at the moment. ✗ is:构不成进行被动;✗ has been:现在完成被动;✗ will be:将来被动。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp3','choice','{"stem":"\"Things like this ___ only a few times before.\"(很少被见过:现在完成被动)","options":["are seeing","have seen","have been seen","saw"],"answer_index":2,"stem_cn":"这样的东西以前只被见过几次。","explanation_cn":"“(到现在)只被见过几次”,用现在完成的被动 have been + 过去分词。✓ Things like this have been seen only a few times. ✗ saw:一般过去主动;✗ are seeing:进行主动;✗ have seen:现在完成主动。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp3','choice','{"stem":"\"The object ___ for over a hundred years before it was found.\"(曾被遗忘:过去完成被动)","options":["had been forgotten","was forgetting","has forgotten","forgot"],"answer_index":0,"stem_cn":"这件物品被发现前,已被遗忘了一百多年。","explanation_cn":"“(被发现之前)早已被遗忘”,用过去完成的被动 had been + 过去分词。✓ The object had been forgotten for over a hundred years. ✗ forgot:一般过去主动;✗ was forgetting:进行主动;✗ has forgotten:现在完成主动。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp3','choice','{"stem":"\"It ___ to the museum already.\"(已被送到:现在完成被动)","options":["is sending","sent","has been sent","sends"],"answer_index":2,"stem_cn":"它已经被送到博物馆了。","explanation_cn":"“已经被送到”,用现在完成的被动。✓ It has been sent to the museum already. ✗ sent:一般过去主动;✗ is sending:进行主动;✗ sends:一般现在主动。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp4','choice','{"stem":"\"Every valuable piece ___ in a special room.\"(被保存:一般现在被动)","options":["is kept","is keeping","has kept","keeps"],"answer_index":0,"stem_cn":"每件珍贵的物品都被保存在一个专门的房间里。","explanation_cn":"“(经常性地)被保存”,用一般现在的被动 is + 过去分词。✓ Every valuable piece is kept in a special room. ✗ keeps:一般现在主动;✗ is keeping:进行主动;✗ has kept:现在完成主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp4','choice','{"stem":"\"Each object ___ daily by the staff.\"(被检查:一般现在被动)","options":["checks","checked","is checking","is checked"],"answer_index":3,"stem_cn":"每件物品每天都由工作人员检查。","explanation_cn":"“每天被检查”,用一般现在的被动。✓ Each object is checked daily. ✗ checks:一般现在主动;✗ is checking:进行主动;✗ checked:缺 be，构不成现在被动。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp4','choice','{"stem":"\"Next month, the object ___ to the public.\"(将被展出:将来被动)","options":["shows","will be shown","will show","is showing"],"answer_index":1,"stem_cn":"下个月,这件物品将向公众展出。","explanation_cn":"“将来被展出”,用将来的被动 will be + 过去分词。✓ the object will be shown to the public. ✗ will show:将来主动;✗ is showing:进行主动;✗ shows:一般现在主动。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp5','choice','{"stem":"\"At first the family ___ it, thinking it was junk.\"(嘲笑、取笑用哪个词组)","options":["laughed at","washed","washed up","laughed"],"answer_index":0,"stem_cn":"起初,一家人还嘲笑它,以为是废物。","explanation_cn":"“嘲笑、取笑(某物某人)”用 laugh at。✓ the family laughed at it. ✗ laughed:单纯地笑,不带“取笑”对象;✗ washed:是“洗”;✗ washed up:是“洗餐具/冲上岸”。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp5','choice','{"stem":"\"Everybody ___ when the clown appeared.\"(单纯地“笑”用哪个词)","options":["washed up","laughed at","laughed","washed"],"answer_index":2,"stem_cn":"小丑出场时,大家都笑了。","explanation_cn":"单纯地“笑”(高兴地笑)用 laugh。✓ Everybody laughed when the clown appeared. ✗ laughed at:是“嘲笑(某人)”，这里不是取笑;✗ washed / washed up:与“笑”无关。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp5','choice','{"stem":"\"What a lot of dirty dishes! Who is going to ___?\"(洗餐具用哪个词组)","options":["wash down","laugh at","laugh","wash up"],"answer_index":3,"stem_cn":"这么多脏盘子!谁来洗?","explanation_cn":"“洗餐具、洗碗碟”用 wash up。✓ Who is going to wash up? ✗ laugh at:是“嘲笑”;✗ wash down:是“冲洗(墙面等)”;✗ laugh:是“笑”。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp6','choice','{"stem":"\"The old object was kept in a dusty ___ under the roof.\"(阁楼用哪个词)","options":["kitchen","attic","garage","garden"],"answer_index":1,"stem_cn":"这件旧物一直放在屋顶下积满灰尘的阁楼里。","explanation_cn":"屋顶下堆放旧物的“阁楼”是 attic。✓ kept in a dusty attic under the roof. ✗ garden:是“花园”;✗ kitchen:是“厨房”;✗ garage:是“车库”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp6','choice','{"stem":"\"The object is now studied by ___ at the museum.\"(专家用哪个词)","options":["students","children","tourists","experts"],"answer_index":3,"stem_cn":"这件物品现在由博物馆的专家们研究。","explanation_cn":"研究、鉴定的“专家”是 expert(复数 experts)。✓ studied by experts at the museum. ✗ tourists:是“游客”;✗ students:是“学生”;✗ children:是“孩子”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',5,'am2_l82_gp6','choice','{"stem":"\"It turned out to be very old and ___.\"(珍贵的用哪个词)","options":["valuable","ordinary","worthless","empty"],"answer_index":0,"stem_cn":"结果发现它非常古老而珍贵。","explanation_cn":"“珍贵的、值钱的”是 valuable。✓ very old and valuable. ✗ worthless:是“毫无价值的”;✗ ordinary:是“普通的”;✗ empty:是“空的”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"美语里\"垃圾\"常说:","options":["rubbish","trash","waste-stuff","throw-things"],"answer_index":1,"explanation_cn":"美语“垃圾”说 trash;英式说 rubbish。✓ Throw it in the trash. 把它扔进垃圾桶。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"美语里\"手电筒\"常说:","options":["torch","hand-lamp","flashlight","light-stick"],"answer_index":2,"explanation_cn":"美语“手电筒”说 flashlight;英式说 torch。✓ He used a flashlight in the dark attic. 他在黑暗的阁楼里用手电筒。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"attic 的意思是:","options":["厨房","阁楼","地下室","车库"],"answer_index":1,"explanation_cn":"attic = 阁楼(屋顶下的空间)。✓ found in the attic 在阁楼里发现。\n顺带记:地下室 = basement;厨房 = kitchen;车库 = garage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"examine 的意思是:","options":["检查,鉴定","出售","隐藏","丢弃"],"answer_index":0,"explanation_cn":"examine = 检查、鉴定。✓ the object is being examined 物品正在被鉴定。\n顺带记:出售 = sell;丢弃 = throw away;隐藏 = hide."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"valuable 的意思是:","options":["普通的","珍贵的","廉价的","破旧的"],"answer_index":1,"explanation_cn":"valuable = 珍贵的、值钱的。✓ every valuable piece 每件珍贵的物品。\n顺带记:廉价的 = cheap;普通的 = ordinary;破旧的 = shabby."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',6,NULL,'choice','{"stem":"curious 的意思是:","options":["好奇的;奇特的","愤怒的","疲惫的","无聊的"],"answer_index":0,"explanation_cn":"curious = 好奇的;也可指“奇特的”。✓ a curious pattern 一个奇特的图案。\n顺带记:无聊的 = bored;愤怒的 = angry;疲惫的 = tired."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',7,NULL,'cloze','{"stem":"第 1 空","context":"Last week a strange object ___1___ in the attic. It ___2___ in dust for years. Now it ___3___ examined by experts, and next month it ___4___ shown to the public.","blank_no":1,"options":["was found","found","is found","was finding"],"answer_index":0,"explanation_cn":"过去“被发现”,用一般过去被动。✓ a strange object was found in the attic.\n✗ found:主动;✗ is found:一般现在;✗ was finding:进行主动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',7,NULL,'cloze','{"stem":"第 2 空","context":"Last week a strange object ___1___ in the attic. It ___2___ in dust for years. Now it ___3___ examined by experts, and next month it ___4___ shown to the public.","blank_no":2,"options":["was covered","covered","is covering","covers"],"answer_index":0,"explanation_cn":"过去“被灰尘覆盖”,用一般过去被动。✓ It was covered in dust.\n✗ covered:主动;✗ is covering:进行主动;✗ covers:一般现在主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',7,NULL,'cloze','{"stem":"第 3 空","context":"Last week a strange object ___1___ in the attic. It ___2___ in dust for years. Now it ___3___ examined by experts, and next month it ___4___ shown to the public.","blank_no":3,"options":["is being","is","has been","was"],"answer_index":0,"explanation_cn":"此刻“正在被鉴定”,用现在进行被动 is being + 过去分词。✓ it is being examined by experts.\n✗ is:构不成进行被动;✗ has been:现在完成被动;✗ was:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',7,NULL,'cloze','{"stem":"第 4 空","context":"Last week a strange object ___1___ in the attic. It ___2___ in dust for years. Now it ___3___ examined by experts, and next month it ___4___ shown to the public.","blank_no":4,"options":["will be","will","is","was"],"answer_index":0,"explanation_cn":"“将被展出”,用将来被动 will be + 过去分词。✓ it will be shown to the public.\n✗ will:构不成被动;✗ is:一般现在;✗ was:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',8,NULL,'choice','{"stem":"Where was the strange object found?","options":["In the attic of an old house","In the city museum","On a beach","In a garden"],"answer_index":0,"explanation_cn":"课文说 a strange old object was found in the attic of an old house。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',8,NULL,'choice','{"stem":"What is happening to the object now?","options":["It is being sold","It is being repainted","It has been thrown away","It is being examined by experts at the museum"],"answer_index":3,"explanation_cn":"课文说 Now the object is being examined by experts at the city museum。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',8,NULL,'choice','{"stem":"What will happen next month?","options":["It will be returned to the attic","It will be sold abroad","It will be shown to the public for the first time","It will be destroyed"],"answer_index":2,"explanation_cn":"课文说 Next month, the mysterious object will be shown to the public for the first time。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',9,NULL,'choice','{"stem":"你想说\"上周在阁楼里发现了一件旧物\"(一般过去被动):","options":["Last week an old object has found in the attic.","Last week an old object was finding in the attic.","Last week an old object was found in the attic.","Last week an old object found in the attic."],"answer_index":2,"explanation_cn":"过去“被发现”用一般过去被动 was + 过去分词。✓ an old object was found in the attic. 场合:说某物在过去被(人)发现。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',9,NULL,'choice','{"stem":"你想说\"这件物品正由专家鉴定\"(现在进行被动):","options":["The object is being examined by experts.","The object is examining by experts.","The object has examined by experts.","The object is examined by experts now."],"answer_index":0,"explanation_cn":"此刻“正在被鉴定”用现在进行被动 is being + 过去分词。✓ The object is being examined by experts. 场合:说某物此刻正被处理。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',9,NULL,'choice','{"stem":"你想说\"下个月它将向公众展出\"(将来被动):","options":["Next month it will show to the public.","Next month it will be shown to the public.","Next month it was shown to the public.","Next month it is shown to the public."],"answer_index":1,"explanation_cn":"“将被展出”用将来被动 will be + 过去分词。✓ Next month it will be shown to the public. 场合:说某事将来会被做。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"attic 的意思是:","options":["车库","地下室","阁楼","厨房"],"answer_index":2,"explanation_cn":"attic = 阁楼。✓ found in the attic 在阁楼里发现。\n顺带记:地下室 = basement;厨房 = kitchen;车库 = garage."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"valuable 的意思是:","options":["廉价的","珍贵的","破旧的","普通的"],"answer_index":1,"explanation_cn":"valuable = 珍贵的、值钱的。✓ every valuable piece 每件珍贵的物品。\n顺带记:廉价的 = cheap;普通的 = ordinary;破旧的 = shabby."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"\"A strange object ___ in the attic.\"(一般过去被动)","options":["was found","was finding","found","is found"],"answer_index":0,"stem_cn":"在阁楼里发现了一件古怪的旧物。","explanation_cn":"过去“被发现”,用一般过去被动。✓ a strange object was found in the attic.\n✗ found:主动;✗ is found:一般现在;✗ was finding:进行主动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"\"The object ___ by experts right now.\"(现在进行被动)","options":["examines","is examining","is examined","is being examined"],"answer_index":3,"stem_cn":"这件物品此刻正由专家鉴定。","explanation_cn":"此刻“正在被鉴定”,用现在进行被动。✓ The object is being examined by experts right now.\n✗ is examined:一般现在被动;✗ is examining:进行主动;✗ examines:一般现在主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"\"laugh at\" 的意思是:","options":["开怀大笑","冲上岸","嘲笑、取笑","洗餐具"],"answer_index":2,"explanation_cn":"laugh at = 嘲笑、取笑(某人某物);单纯地笑用 laugh。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"\"go on display\" 的意思是:","options":["被出售","(被)展出、陈列","被隐藏","被丢弃"],"answer_index":1,"explanation_cn":"go on display = (被)展出、陈列。如 The object will go on display next month。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"Why did the family laugh at the object at first?","options":["They thought it was junk","It made a funny noise","It looked like a toy","It was very small"],"answer_index":0,"passage":"Last week, a strange old object was found in the attic of an old house. It was covered in dust and had been forgotten for over a hundred years. At first the family laughed at it, thinking it was junk. But when it was cleaned, a curious pattern was discovered underneath. Now the object is being examined by experts at the city museum. \"Things like this have been seen only a few times before,\" one expert said. \"It is carefully studied before anyone can say what it is.\" Every valuable piece is kept in a special room and is checked daily. Next month, the mysterious object will be shown to the public for the first time. The family who once laughed at it are now proud that it will be displayed in a museum.","explanation_cn":"课文说 At first the family laughed at it, thinking it was junk。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"What was discovered when the object was cleaned?","options":["A name and a date","A hidden key","A curious pattern underneath","Nothing at all"],"answer_index":2,"passage":"Last week, a strange old object was found in the attic of an old house. It was covered in dust and had been forgotten for over a hundred years. At first the family laughed at it, thinking it was junk. But when it was cleaned, a curious pattern was discovered underneath. Now the object is being examined by experts at the city museum. \"Things like this have been seen only a few times before,\" one expert said. \"It is carefully studied before anyone can say what it is.\" Every valuable piece is kept in a special room and is checked daily. Next month, the mysterious object will be shown to the public for the first time. The family who once laughed at it are now proud that it will be displayed in a museum.","explanation_cn":"课文说 when it was cleaned, a curious pattern was discovered underneath。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"How long had the object been forgotten?","options":["For over a hundred years","For a whole century exactly","For ten years","For a few days"],"answer_index":0,"audio":"Last week, a strange old object was found in the attic of an old house. It was covered in dust and had been forgotten for over a hundred years. At first the family laughed at it, thinking it was junk. But when it was cleaned, a curious pattern was discovered underneath. Now the object is being examined by experts at the city museum. \"Things like this have been seen only a few times before,\" one expert said. \"It is carefully studied before anyone can say what it is.\" Every valuable piece is kept in a special room and is checked daily. Next month, the mysterious object will be shown to the public for the first time. The family who once laughed at it are now proud that it will be displayed in a museum.","explanation_cn":"课文说 It… had been forgotten for over a hundred years。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l82',10,NULL,'choice','{"stem":"How does the family feel now?","options":["Sad that it was junk","Angry that it was taken away","Worried about losing it","Proud that it will be displayed in a museum"],"answer_index":3,"audio":"Last week, a strange old object was found in the attic of an old house. It was covered in dust and had been forgotten for over a hundred years. At first the family laughed at it, thinking it was junk. But when it was cleaned, a curious pattern was discovered underneath. Now the object is being examined by experts at the city museum. \"Things like this have been seen only a few times before,\" one expert said. \"It is carefully studied before anyone can say what it is.\" Every valuable piece is kept in a special room and is checked daily. Next month, the mysterious object will be shown to the public for the first time. The family who once laughed at it are now proud that it will be displayed in a museum.","explanation_cn":"课文说 The family who once laughed at it are now proud that it will be displayed in a museum。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l83',2,11,83,'The Election Results','选举结果','复习 KS74-82 各时态综合(教材 L83 Key structures,方案B换情节包):一般现在(holds)、过去进行(were running/was watching)、一般过去(gathered/was)、过去完成被动(had been counted)、现在完成进行(have been waiting)、现在进行(is announcing/is planning)、现在完成(has won/have never felt)的综合运用辨析','每年,我们学校都会举办一次社长选举。今年,有三名学生参加竞选,全校都在关注。上周五,大家聚在礼堂里等着听结果。等我到的时候,选票已经清点完了。“同学们为这一刻等了整整一周,”老师说。此刻,校长正在宣布获胜者。米娅仅以五票之差赢了!她惊讶得一时说不出话来。“我从没这么高兴过,”她终于说道。现在,她正在筹划社团今年要办的所有趣味活动。','{"q":"Listen and answer — Who won the club election, and by how much?","options":["Mia won, by just five votes","Mia won, by fifty votes","The teacher won","No one won — it was a tie"],"answer_index":0}'::jsonb,'{"title":"复习 KS74-82 各时态综合","intro":"本课把学过的各种时态放在一个故事里综合辨析:①一般现在——每年都做的事(our school holds an election);②过去进行——过去某时正在做(three students were running / the school was watching);③一般过去——过去发生的事(everyone gathered);④过去完成(被动)——“过去的过去”(the votes had already been counted);⑤现在完成进行——一直做到现在(students have been waiting all week);⑥现在进行——此刻正在做(the principal is announcing / she is planning);⑦现在完成——影响到现在(Mia has won / I have never felt this happy)。","table":{"headers":["时态","例子"],"rows":[["一般现在","Every year our school holds an election."],["过去进行","Three students were running; the school was watching."],["一般过去 / 过去完成被动","Everyone gathered. / The votes had been counted."],["现在完成进行","The students have been waiting all week."],["现在进行 / 现在完成","The principal is announcing… / Mia has won!"]]},"specialRules":[{"rule":"美语里“校长”说 principal(英式 headmaster/head teacher)、“成绩、分数”说 grade(英式 mark);本课已按美语写。","mark":"principal / grade"},{"rule":"同一个故事里各时态各司其职:每年惯例用一般现在,当时背景用过去进行,已完成影响现在用现在完成,此刻正做用现在进行。看时间标志选时态。","mark":"时态辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l83',1,NULL,'Every year, our school holds an election for club president. This year, three students were running, and the whole school was watching.','每年,我们学校都会举办一次社长选举。今年,有三名学生参加竞选,全校都在关注。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l83',2,NULL,'Last Friday, everyone gathered in the hall to hear the results. By the time I arrived, the votes had already been counted.','上周五,大家聚在礼堂里等着听结果。等我到的时候,选票已经清点完了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l83',3,NULL,'"The students have been waiting all week for this," the teacher said. Right now, the principal is announcing the winner.','“同学们为这一刻等了整整一周,”老师说。此刻,校长正在宣布获胜者。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l83',4,NULL,'Mia has won by just five votes! She was so surprised that she couldn''t speak for a moment.','米娅仅以五票之差赢了!她惊讶得一时说不出话来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l83',5,NULL,'"I have never felt this happy," she finally said. Now she is planning all the fun events the club will hold this year.','“我从没这么高兴过,”她终于说道。现在,她正在筹划社团今年要办的所有趣味活动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
