INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l83','by the time','',NULL,'/baɪ ðə taɪm/','By the time I arrived, the votes had been counted.','我到的时候,选票已经清点完了。','By the time she called, I had already left.','她打电话时,我已经走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
