INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp1','choice','{"stem":"\"Every year, our school ___ an election for club president.\"(每年惯例:一般现在)","options":["holds","held","is holding","has held"],"answer_index":0,"stem_cn":"每年,我们学校都举办社长选举。","explanation_cn":"每年都做的惯例,用一般现在时。✓ Every year our school holds an election. ✗ is holding:现在进行,表此刻;✗ held:一般过去;✗ has held:现在完成。\n每年重复发生的事,一律用一般现在时(动词第三人称加 s)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp1','choice','{"stem":"\"The winner usually ___ the club for one year.\"(通常做的事:一般现在)","options":["has led","leads","led","is leading"],"answer_index":1,"stem_cn":"获胜者通常领导社团一年。","explanation_cn":"“通常领导一年”是惯常的事,用一般现在时。✓ The winner usually leads the club for one year. ✗ is leading:进行,表此刻正在;✗ led:一般过去;✗ has led:现在完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp1','choice','{"stem":"\"The election ___ place in the hall each spring.\"(每年春天惯例:一般现在)","options":["has taken","is taking","took","takes"],"answer_index":3,"stem_cn":"选举每年春天在礼堂举行。","explanation_cn":"“每年春天举行”是惯例,用一般现在时。✓ The election takes place in the hall each spring. ✗ is taking:进行;✗ took:一般过去;✗ has taken:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp2','choice','{"stem":"\"This year, three students ___ for president.\"(当时正在竞选:过去进行)","options":["have run","were running","ran","run"],"answer_index":1,"stem_cn":"今年,有三名学生在竞选社长。","explanation_cn":"过去某段时间“正在竞选”,用过去进行时 were + doing。✓ Three students were running for president. ✗ ran:一般过去,只陈述发生过;✗ run:一般现在;✗ have run:现在完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp2','choice','{"stem":"\"The whole school ___ the election closely.\"(当时正密切关注:过去进行)","options":["watched","has watched","was watching","watches"],"answer_index":2,"stem_cn":"全校都在密切关注这次选举。","explanation_cn":"过去那段时间“正在关注”,用过去进行时 was + doing。✓ The whole school was watching the election closely. ✗ watched:一般过去;✗ watches:一般现在;✗ has watched:现在完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp2','choice','{"stem":"\"While the votes ___ counted, everyone waited nervously.\"(当时正被清点:过去进行被动)","options":["are being","were being","had been","were"],"answer_index":1,"stem_cn":"选票正在清点时,大家紧张地等着。","explanation_cn":"过去“正在被清点”,用过去进行的被动 were being + 过去分词。✓ While the votes were being counted, everyone waited. ✗ were:构不成进行被动;✗ are being:现在;✗ had been:过去完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp3','choice','{"stem":"\"Last Friday, everyone ___ in the hall to hear the results.\"(gather 的过去式)","options":["is gathering","has gathered","gathers","gathered"],"answer_index":3,"stem_cn":"上周五,大家聚在礼堂听结果。","explanation_cn":"过去某天发生的事,用一般过去时(gather 的过去式 gathered)。✓ Last Friday, everyone gathered in the hall. ✗ gathers:一般现在;✗ is gathering:现在进行;✗ has gathered:现在完成。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp3','choice','{"stem":"\"Mia ___ so surprised that she couldn''t speak.\"(be 的过去式)","options":["has been","had been","was","is"],"answer_index":2,"stem_cn":"米娅惊讶得一时说不出话。","explanation_cn":"过去“(当时)很惊讶”,用 be 的过去式 was。✓ Mia was so surprised that she couldn''t speak. ✗ is:一般现在;✗ has been:现在完成;✗ had been:过去完成。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp3','choice','{"stem":"\"By the time I ___, the results were already in.\"(arrive 的过去式)","options":["have arrived","arrive","was arriving","arrived"],"answer_index":3,"stem_cn":"我到的时候,结果已经出来了。","explanation_cn":"“我到的时候”是过去发生的动作,用一般过去时。✓ By the time I arrived, the results were already in. ✗ arrive:一般现在;✗ have arrived:现在完成;✗ was arriving:进行,与瞬间到达不搭。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp4','choice','{"stem":"\"Mia ___ by just five votes!\"(刚刚赢了、影响到现在:现在完成)","options":["had won","has won","is winning","won"],"answer_index":1,"stem_cn":"米娅仅以五票之差赢了!","explanation_cn":"刚刚赢了、结果影响到现在,用现在完成时 has + 过去分词。✓ Mia has won by just five votes! ✗ won:一般过去,只说过去发生;✗ is winning:进行;✗ had won:过去完成。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp4','choice','{"stem":"\"The students ___ all week for this result.\"(一直在等:现在完成进行)","options":["wait","are waiting","waited","have been waiting"],"answer_index":3,"stem_cn":"学生们为这个结果等了整整一周。","explanation_cn":"从过去一直持续等到现在,用现在完成进行时 have been + doing。✓ The students have been waiting all week. ✗ waited:一般过去;✗ wait:一般现在;✗ are waiting:现在进行,不强调“一整周持续”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp4','choice','{"stem":"\"''I ___ this happy before,'' Mia said.\"(从未这么高兴过:现在完成)","options":["had never felt","have never felt","never felt","am never feeling"],"answer_index":1,"stem_cn":"“我从没这么高兴过,”米娅说。","explanation_cn":"“从未有过这种感觉”,经验类,用现在完成时 have + 过去分词。✓ I have never felt this happy before. ✗ never felt:缺 have,构不成现在完成;✗ am never feeling:进行;✗ had never felt:过去完成。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp5','choice','{"stem":"\"By the time I arrived, the votes had already ___.\"(此前已被清点完:过去完成被动)","options":["being counted","count","been counted","counted"],"answer_index":2,"stem_cn":"我到时,选票已经清点完了。","explanation_cn":"“我到之前就已经被清点完”,是“过去的过去”且被动,用过去完成被动 had been + 过去分词。✓ the votes had already been counted. ✗ counted:主动;✗ being counted:缺 had;✗ count:原形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp5','choice','{"stem":"\"Right now, the principal ___ the winner.\"(此刻正在宣布:现在进行)","options":["is announcing","announced","has announced","announces"],"answer_index":0,"stem_cn":"此刻,校长正在宣布获胜者。","explanation_cn":"此刻正在宣布,用现在进行时 is + doing。✓ Right now, the principal is announcing the winner. ✗ announces:一般现在;✗ announced:一般过去;✗ has announced:现在完成。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp5','choice','{"stem":"\"Now Mia ___ all the fun events for this year.\"(现在正在筹划:现在进行)","options":["planned","has planned","is planning","plans"],"answer_index":2,"stem_cn":"现在,米娅正在筹划今年所有的趣味活动。","explanation_cn":"现在这段时间正在筹划,用现在进行时。✓ Now Mia is planning all the fun events. ✗ plans:一般现在;✗ planned:一般过去;✗ has planned:现在完成。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp6','choice','{"stem":"\"Three students are running for club ___.\"(社长、主席用哪个词)","options":["president","guest","driver","teacher"],"answer_index":0,"stem_cn":"三名学生在竞选社长。","explanation_cn":"“社长、主席”是 president。✓ running for club president. ✗ teacher:老师;✗ guest:客人;✗ driver:司机。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp6','choice','{"stem":"\"After the votes were counted, the ___ was announced.\"(获胜者用哪个词)","options":["loser","singer","judge","winner"],"answer_index":3,"stem_cn":"选票清点后,宣布了获胜者。","explanation_cn":"“获胜者”是 winner。✓ the winner was announced. ✗ loser:失败者;✗ judge:裁判;✗ singer:歌手。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',5,'am2_l83_gp6','choice','{"stem":"\"The ___ announced the results to the whole school.\"(校长用哪个词)","options":["student","guard","principal","cook"],"answer_index":2,"stem_cn":"校长向全校宣布了结果。","explanation_cn":"“校长”是 principal。✓ The principal announced the results. ✗ student:学生;✗ cook:厨师;✗ guard:门卫。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"美语里\"校长\"常说:","options":["principal","headmaster","top-teacher","school-boss"],"answer_index":0,"explanation_cn":"美语“校长”说 principal;英式说 headmaster/head teacher。✓ The principal spoke to the whole school. 校长向全校讲话。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"美语里\"成绩、分数\"常说:","options":["mark","score-point","class-number","grade"],"answer_index":3,"explanation_cn":"美语“成绩、分数”说 grade;英式说 mark。✓ She got a good grade on the test. 她考试得了好成绩。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"election 的意思是:","options":["比赛","选举","考试","假期"],"answer_index":1,"explanation_cn":"election = 选举。✓ an election for club president 社长选举。\n顺带记:考试 = exam/test;假期 = vacation;比赛 = race/contest."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"announce 的意思是:","options":["隐瞒","询问","取消","宣布"],"answer_index":3,"explanation_cn":"announce = 宣布。✓ the principal is announcing the winner 校长正在宣布获胜者。\n顺带记:隐瞒 = hide;询问 = ask;取消 = cancel."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"gather 的意思是:","options":["离开","聚集","奔跑","睡觉"],"answer_index":1,"explanation_cn":"gather = 聚集。✓ everyone gathered in the hall 大家聚在礼堂里。\n顺带记:离开 = leave;睡觉 = sleep;奔跑 = run."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',6,NULL,'choice','{"stem":"winner 的意思是:","options":["获胜者","观众","裁判","失败者"],"answer_index":0,"explanation_cn":"winner = 获胜者。✓ announcing the winner 宣布获胜者。\n顺带记:失败者 = loser;裁判 = judge/referee;观众 = audience."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',7,NULL,'cloze','{"stem":"第 1 空","context":"Every year our school ___1___ an election. This year three students ___2___ for president. By the time I arrived, the votes had already ___3___. Now Mia, the winner, ___4___ the club''s events.","blank_no":1,"options":["holds","is holding","held","has held"],"answer_index":0,"explanation_cn":"每年惯例,用一般现在时。✓ Every year our school holds an election.\n✗ is holding:进行;✗ held:一般过去;✗ has held:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',7,NULL,'cloze','{"stem":"第 2 空","context":"Every year our school ___1___ an election. This year three students ___2___ for president. By the time I arrived, the votes had already ___3___. Now Mia, the winner, ___4___ the club''s events.","blank_no":2,"options":["were running","ran","run","have run"],"answer_index":0,"explanation_cn":"过去某段时间正在竞选,用过去进行时。✓ Three students were running for president.\n✗ ran:一般过去;✗ run:一般现在;✗ have run:现在完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',7,NULL,'cloze','{"stem":"第 3 空","context":"Every year our school ___1___ an election. This year three students ___2___ for president. By the time I arrived, the votes had already ___3___. Now Mia, the winner, ___4___ the club''s events.","blank_no":3,"options":["been counted","counted","being counted","count"],"answer_index":0,"explanation_cn":"“我到之前已被清点完”,过去完成被动 had already + been + 过去分词。✓ the votes had already been counted.\n✗ counted:主动;✗ being counted:缺 had;✗ count:原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',7,NULL,'cloze','{"stem":"第 4 空","context":"Every year our school ___1___ an election. This year three students ___2___ for president. By the time I arrived, the votes had already ___3___. Now Mia, the winner, ___4___ the club''s events.","blank_no":4,"options":["is planning","plans","planned","has planned"],"answer_index":0,"explanation_cn":"现在正在筹划,用现在进行时。✓ Now Mia is planning the club''s events.\n✗ plans:一般现在;✗ planned:一般过去;✗ has planned:现在完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',8,NULL,'choice','{"stem":"What does the school do every year?","options":["Holds a sports day","Holds an election for club president","Takes a trip","Puts on a play"],"answer_index":1,"explanation_cn":"课文说 Every year, our school holds an election for club president。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',8,NULL,'choice','{"stem":"Who won the election this year?","options":["Nobody","The teacher","Mia, by just five votes","A student named Leo"],"answer_index":2,"explanation_cn":"课文说 Mia has won by just five votes!"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',8,NULL,'choice','{"stem":"What is Mia doing now?","options":["Planning all the fun events for the club this year","Counting the votes again","Watching the results","Leaving the school"],"answer_index":0,"explanation_cn":"课文说 Now she is planning all the fun events the club will hold this year。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',9,NULL,'choice','{"stem":"你想说\"今年有三名学生在竞选社长\"(过去进行,当时正在做):","options":["This year, three students run for president.","This year, three students were running for president.","This year, three students have run for president.","This year, three students ran for president once."],"answer_index":1,"explanation_cn":"过去那段时间“正在竞选”,用过去进行时 were + doing。✓ three students were running for president. 场合:描述过去某时正在进行的动作。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',9,NULL,'choice','{"stem":"你想说\"我到的时候,选票已经清点完了\"(过去完成被动,过去的过去):","options":["By the time I arrived, the votes have already been counted.","By the time I arrived, the votes already counted.","By the time I arrived, the votes had already been counted.","By the time I arrived, the votes were counting."],"answer_index":2,"explanation_cn":"“我到之前已被清点完”,过去完成被动 had been + 过去分词。✓ the votes had already been counted. 场合:说某事在过去某时之前就已完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',9,NULL,'choice','{"stem":"你想说\"此刻校长正在宣布获胜者\"(现在进行):","options":["Right now, the principal is announcing the winner.","Right now, the principal announces the winner.","Right now, the principal has announced the winner.","Right now, the principal announced the winner."],"answer_index":0,"explanation_cn":"此刻正在宣布,用现在进行时 is + doing。✓ the principal is announcing the winner. 场合:说某人此刻正在做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"election 的意思是:","options":["考试","选举","比赛","假期"],"answer_index":1,"explanation_cn":"election = 选举。✓ an election for club president 社长选举。\n顺带记:考试 = exam;假期 = vacation;比赛 = race."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"winner 的意思是:","options":["失败者","裁判","观众","获胜者"],"answer_index":3,"explanation_cn":"winner = 获胜者。✓ announcing the winner 宣布获胜者。\n顺带记:失败者 = loser;裁判 = judge;观众 = audience."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"\"Every year our school ___ an election.\"(每年惯例:一般现在)","options":["has held","is holding","holds","held"],"answer_index":2,"stem_cn":"每年我们学校都举办选举。","explanation_cn":"每年惯例,用一般现在时。✓ Every year our school holds an election.\n✗ is holding:进行;✗ held:一般过去;✗ has held:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"\"By the time I arrived, the votes had already ___.\"(过去完成被动)","options":["count","counted","being counted","been counted"],"answer_index":3,"stem_cn":"我到时,选票已经清点完了。","explanation_cn":"“已被清点完”,过去完成被动 had already + been + 过去分词。✓ the votes had already been counted.\n✗ counted:主动;✗ being counted:缺 had;✗ count:原形。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"\"run for president\" 的意思是:","options":["竞选社长/主席","赶去开会","为主席跑腿","跑去找主席"],"answer_index":0,"explanation_cn":"run for president = 竞选社长/主席(run 在这里是“参加竞选”)。✓ Three students were running for president。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"\"by the time\" 的意思是:","options":["偶尔地","到…的时候(为止)","按时地","花时间"],"answer_index":1,"explanation_cn":"by the time = 到…的时候(为止),引出一个时间点,常配过去完成。✓ By the time I arrived, the votes had been counted。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"Why couldn''t Mia speak for a moment?","options":["She had lost her voice","She was very tired","She was reading a speech","She was so surprised at winning"],"answer_index":3,"passage":"Every year, our school holds an election for club president. This year, three students were running, and the whole school was watching. Last Friday, everyone gathered in the hall to hear the results. By the time I arrived, the votes had already been counted. \"The students have been waiting all week for this,\" the teacher said. Right now, the principal is announcing the winner. Mia has won by just five votes! She was so surprised that she couldn''t speak for a moment. \"I have never felt this happy,\" she finally said. Now she is planning all the fun events the club will hold this year.","explanation_cn":"课文说 Mia has won… She was so surprised that she couldn''t speak for a moment。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"How close was the election?","options":["Mia won by a hundred votes","It ended in a tie","Mia won by just five votes","Mia lost by five votes"],"answer_index":2,"passage":"Every year, our school holds an election for club president. This year, three students were running, and the whole school was watching. Last Friday, everyone gathered in the hall to hear the results. By the time I arrived, the votes had already been counted. \"The students have been waiting all week for this,\" the teacher said. Right now, the principal is announcing the winner. Mia has won by just five votes! She was so surprised that she couldn''t speak for a moment. \"I have never felt this happy,\" she finally said. Now she is planning all the fun events the club will hold this year.","explanation_cn":"课文说 Mia has won by just five votes!"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"How long had the students been waiting for the result?","options":["For an hour","Since morning","For a month","All week"],"answer_index":3,"audio":"Every year, our school holds an election for club president. This year, three students were running, and the whole school was watching. Last Friday, everyone gathered in the hall to hear the results. By the time I arrived, the votes had already been counted. \"The students have been waiting all week for this,\" the teacher said. Right now, the principal is announcing the winner. Mia has won by just five votes! She was so surprised that she couldn''t speak for a moment. \"I have never felt this happy,\" she finally said. Now she is planning all the fun events the club will hold this year.","explanation_cn":"课文说 The students have been waiting all week for this。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l83',10,NULL,'choice','{"stem":"How did Mia feel when she won?","options":["Happier than she had ever felt","Bored and tired","Nervous and afraid","Angry and upset"],"answer_index":0,"audio":"Every year, our school holds an election for club president. This year, three students were running, and the whole school was watching. Last Friday, everyone gathered in the hall to hear the results. By the time I arrived, the votes had already been counted. \"The students have been waiting all week for this,\" the teacher said. Right now, the principal is announcing the winner. Mia has won by just five votes! She was so surprised that she couldn''t speak for a moment. \"I have never felt this happy,\" she finally said. Now she is planning all the fun events the club will hold this year.","explanation_cn":"课文说 \"I have never felt this happy,\" she finally said——即她从未这么高兴过。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l84',2,11,84,'The School Play','校园话剧','复习 KS12/36/60 一般将来时(方案B换情节包):will do(将来预测/临时决定)与 be going to do(计划、迹象)的辨析;when/if/as soon as 引导的从句用一般现在时表将来;将来时的否定与疑问','我们班下个月要上演一出话剧。“这会是很大的工作量,”老师说,“但我保证一定很有意思。”等票开始出售时,我们会邀请所有家长来看。米娅打算设计戏服,里奥负责画布景。“万一当天下雨,我们就把一切都搬到室内。”“你打算在剧里唱歌吗?”我问山姆。“是的,我这一周每天晚上都要排练。”演出七点才开始,所以我们有充足的时间准备。灯一暗下来,第一场戏就要开始了。“我觉得这会是我们学校有史以来最棒的一场演出!”','{"q":"Listen and answer — What is the class going to do next month?","options":["Put on a school play","Take a big test","Go on a class trip","Clean the whole school"],"answer_index":0}'::jsonb,'{"title":"复习 KS12/36/60 一般将来时","intro":"本课复习“将来”的两种主要说法及其区别:①will do——对将来的预测,或说话当下临时做的决定(I''m sure it will be fun);②be going to do——事先已定的计划、打算,或根据迹象作的判断(Our class is going to put on a play);③when / if / as soon as 引导的时间、条件从句里,一律用一般现在时表示将来(When the tickets go on sale, we will invite the parents),从句不用 will;④否定用 won''t,疑问把 will 提前或用 Are you going to…。","table":{"headers":["用法","例子"],"rows":[["will do(预测/临时决定)","I''m sure it will be fun. / I''ll help you carry it."],["be going to do(计划/迹象)","Our class is going to put on a play. / It''s going to rain."],["从句用现在表将来","When the tickets go on sale, we will invite the parents."],["否定 / 疑问","The show won''t start until seven. / Are you going to sing?"]]},"specialRules":[{"rule":"美语“剧院、戏院”常写 theater(英式 theatre);“排队”说 stand in line(英式 queue)。本课已按美语写。","mark":"theater / line"},{"rule":"已定的计划用 be going to,当场的决定用 will,迹象征兆判断用 be going to;when/if/as soon as 从句里用现在时,别用 will。","mark":"将来时辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l84',1,NULL,'Our class is going to put on a play next month. "It will be a lot of work," the teacher said, "but I''m sure it will be fun."','我们班下个月要上演一出话剧。“这会是很大的工作量,”老师说,“但我保证一定很有意思。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l84',2,NULL,'When the tickets go on sale, we will invite all the parents. Mia is going to design the costumes, and Leo will paint the background.','等票开始出售时,我们会邀请所有家长来看。米娅打算设计戏服,里奥负责画布景。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l84',3,NULL,'"If it rains on the day, we will move everything indoors." "Are you going to sing in the play?" I asked Sam.','“万一当天下雨,我们就把一切都搬到室内。”“你打算在剧里唱歌吗?”我问山姆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l84',4,NULL,'"Yes, I am. I am going to practice every evening this week." The show won''t start until seven, so we will have time to get ready.','“是的。我这一周每天晚上都要排练。”演出七点才开始,所以我们有充足的时间准备。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l84',5,NULL,'As soon as the lights go down, the first scene will begin. "I think this is going to be the best play our school has ever seen!"','灯一暗下来,第一场戏就要开始了。“我觉得这会是我们学校有史以来最棒的一场演出!”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
