INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l84','put on a play','',NULL,'/pʊt ɑːn ə pleɪ/','Our class is going to put on a play.','我们班要上演一出话剧。','They put on a wonderful show every spring.','他们每年春天都上演一场精彩的演出。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l84','be going to','',NULL,'/bi ˈɡoʊɪŋ tu/','Mia is going to design the costumes.','米娅打算设计戏服。','Look at the clouds — it is going to rain.','看那些云——要下雨了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l84','on sale','',NULL,'/ɑːn seɪl/','When the tickets go on sale, we will invite the parents.','票开始出售时,我们会邀请家长。','The new books are on sale now.','新书现在开始发售了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l84','as soon as','',NULL,'/əz suːn əz/','As soon as the lights go down, the first scene will begin.','灯一暗,第一场戏就开始。','As soon as she arrives, we will start.','她一到,我们就开始。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp1','choice','{"stem":"\"The teacher is sure the play ___ a lot of fun.\"(对将来的预测)","options":["will be","has been","was","is being"],"answer_index":0,"stem_cn":"老师确信这出戏会很有意思。","explanation_cn":"对将来的预测,用 will + 动词原形。✓ The play will be a lot of fun. ✗ is being:现在进行;✗ was:过去;✗ has been:现在完成。\n预测将来会怎样,一般用 will。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp1','choice','{"stem":"\"That box looks heavy — I ___ you carry it,\" Leo said.(当场作出的决定)","options":["help","helped","am helping","will help"],"answer_index":3,"stem_cn":"“那箱子看着挺重,我来帮你搬,”里奥说。","explanation_cn":"看到箱子重,说话当下临时决定去帮忙,用 will。✓ I will help you carry it. ✗ am helping:现在进行;✗ helped:过去;✗ help:一般现在。\n临时、当场作出的决定用 will,不用 be going to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp1','choice','{"stem":"\"I think this ___ the best play ever!\" Mia said.(对将来的预测)","options":["was","will be","is being","is"],"answer_index":1,"stem_cn":"“我觉得这会是有史以来最棒的戏!”米娅说。","explanation_cn":"对将来的预测(“会是最棒的戏”),用 will。✓ This will be the best play ever. ✗ is being:进行;✗ was:过去;✗ is:一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp2','choice','{"stem":"\"Our class ___ put on a play next month.\"(事先已定的计划)","options":["will going to","be going to","is going","is going to"],"answer_index":3,"stem_cn":"我们班下个月要上演一出话剧。","explanation_cn":"事先已定的计划、打算,用 be going to + 动词原形。✓ Our class is going to put on a play. ✗ is going:缺 to;✗ will going to:will 与 going to 不能连用;✗ be going to:缺 is。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp2','choice','{"stem":"\"Mia ___ design the costumes this week.\"(事先已定的打算)","options":["is going to","is going","be going to","are going to"],"answer_index":0,"stem_cn":"米娅这周打算设计戏服。","explanation_cn":"事先已定的打算,用 be going to。✓ Mia is going to design the costumes. ✗ is going:缺 to;✗ are going to:Mia 是单数,应配 is;✗ be going to:缺 is。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp2','choice','{"stem":"\"Are you ___ sing in the play?\" Sam was asked.(打算做某事的疑问)","options":["going","go to","going to","will to"],"answer_index":2,"stem_cn":"有人问山姆:“你打算在剧里唱歌吗?”","explanation_cn":"问“打算做某事吗”,用 Are you going to + 原形。✓ Are you going to sing? ✗ go to:少了 -ing;✗ going:缺 to;✗ will to:will 后不加 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp3','choice','{"stem":"\"When the tickets ___ on sale, we will invite the parents.\"(when 从句里表将来)","options":["will go","are going","went","go"],"answer_index":3,"stem_cn":"票开始出售时,我们会邀请家长。","explanation_cn":"when 引导的时间从句里,用一般现在时表示将来,主句才用 will。✓ When the tickets go on sale, we will invite the parents. ✗ will go:从句里不用 will;✗ are going:进行;✗ went:过去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp3','choice','{"stem":"\"If it ___ on the day, we will move indoors.\"(if 从句里表将来)","options":["rains","is raining","will rain","rained"],"answer_index":0,"stem_cn":"如果那天下雨,我们就搬到室内。","explanation_cn":"if 引导的条件从句里,用一般现在时表示将来。✓ If it rains on the day, we will move indoors. ✗ will rain:从句里不用 will;✗ is raining:进行;✗ rained:过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp3','choice','{"stem":"\"As soon as the lights ___ down, the first scene will begin.\"(as soon as 从句里表将来)","options":["will go","go","are going","went"],"answer_index":1,"stem_cn":"灯一暗,第一场戏就开始。","explanation_cn":"as soon as 引导的时间从句里,用一般现在时表示将来。✓ As soon as the lights go down, the first scene will begin. ✗ will go:从句里不用 will;✗ are going:进行;✗ went:过去。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp4','choice','{"stem":"\"The show ___ start until seven.\"(将来时的否定)","options":["doesn''t","isn''t","didn''t","won''t"],"answer_index":3,"stem_cn":"演出七点才开始。","explanation_cn":"将来时的否定,用 won''t(= will not)+ 动词原形。✓ The show won''t start until seven. ✗ doesn''t:一般现在否定;✗ isn''t:与原形 start 不搭;✗ didn''t:过去否定。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp4','choice','{"stem":"\"___ you invite your parents to the play?\"(将来时的一般疑问)","options":["Did","Are","Will","Do"],"answer_index":2,"stem_cn":"你会邀请父母来看戏吗?","explanation_cn":"将来时的一般疑问,把 Will 提到句首 + 动词原形。✓ Will you invite your parents? ✗ Do:一般现在;✗ Are:与原形 invite 不搭;✗ Did:过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp4','choice','{"stem":"\"Don''t worry — I ___ be late,\" Mia promised.(将来时的否定)","options":["won''t","am not","don''t","didn''t"],"answer_index":0,"stem_cn":"“别担心,我不会迟到,”米娅保证道。","explanation_cn":"表将来的否定决定,用 won''t + 动词原形。✓ I won''t be late. ✗ don''t:一般现在;✗ am not:与原形 be 不搭;✗ didn''t:过去。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp5','choice','{"stem":"\"Look at those dark clouds! It ___ rain.\"(有迹象、征兆的判断)","options":["going to","is going to","will going","is go to"],"answer_index":1,"stem_cn":"看那乌云!要下雨了。","explanation_cn":"看到乌云这一迹象来判断将要发生的事,用 be going to。✓ It is going to rain. ✗ is go to:少了 -ing;✗ will going:will 与 going 不能连用;✗ going to:缺 is。\n有征兆、迹象在眼前的判断,用 be going to 更自然。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp5','choice','{"stem":"\"The phone is ringing. I ___ answer it,\" Mia said.(说话当下临时决定)","options":["will","am go to","going to","will to"],"answer_index":0,"stem_cn":"“电话响了,我去接,”米娅说。","explanation_cn":"电话此刻响起,当场决定去接,用 will。✓ I will answer it. ✗ am go to:错形;✗ going to:缺 be;✗ will to:will 后不加 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp5','choice','{"stem":"\"As soon as the show ___, we will clean up,\" the teacher said.(as soon as 从句里表将来)","options":["is ending","ended","ends","will end"],"answer_index":2,"stem_cn":"“演出一结束,我们就打扫,”老师说。","explanation_cn":"as soon as 引导的时间从句里,用一般现在时表将来。✓ As soon as the show ends, we will clean up. ✗ will end:从句里不用 will;✗ is ending:进行;✗ ended:过去。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp6','choice','{"stem":"\"The actors will wear beautiful ___ on stage.\"(戏服用哪个词)","options":["costumes","lights","tickets","seats"],"answer_index":0,"stem_cn":"演员们将在台上穿漂亮的戏服。","explanation_cn":"演员穿的“戏服”是 costume(复数 costumes)。✓ wear beautiful costumes on stage. ✗ tickets:门票;✗ lights:灯光;✗ seats:座位。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp6','choice','{"stem":"\"Mia will ___ the costumes for the play.\"(设计用哪个词)","options":["eat","design","watch","lose"],"answer_index":1,"stem_cn":"米娅将为这出戏设计戏服。","explanation_cn":"“设计”是 design。✓ Mia will design the costumes. ✗ watch:观看;✗ eat:吃;✗ lose:丢失。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',5,'am2_l84_gp6','choice','{"stem":"\"We will ___ all the parents to the show.\"(邀请用哪个词)","options":["invite","forget","sell","refuse"],"answer_index":0,"stem_cn":"我们将邀请所有家长来看演出。","explanation_cn":"“邀请”是 invite。✓ We will invite all the parents. ✗ refuse:拒绝;✗ forget:忘记;✗ sell:出售。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"美语里\"剧院、戏院\"常写:","options":["show-room","play-house","theater","theatre"],"answer_index":2,"explanation_cn":"美语“剧院、戏院”常写 theater;英式写 theatre。✓ We watched a play at the theater. 我们在剧院看了一出戏。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"美语里\"排队\"说 stand in ___:","options":["line","file","queue","row"],"answer_index":0,"explanation_cn":"美语“排队”说 stand in line;英式说 queue。✓ We stood in line to buy tickets. 我们排队买票。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"costume 的意思是:","options":["灯光","门票","戏服","布景"],"answer_index":2,"explanation_cn":"costume = 戏服、服装。✓ design the costumes 设计戏服。\n顺带记:门票 = ticket;布景 = background/scenery;灯光 = lights."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"design 的意思是:","options":["出售","设计","观看","忘记"],"answer_index":1,"explanation_cn":"design = 设计。✓ design the costumes 设计戏服。\n顺带记:忘记 = forget;出售 = sell;观看 = watch."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"invite 的意思是:","options":["拒绝","隐藏","邀请","离开"],"answer_index":2,"explanation_cn":"invite = 邀请。✓ invite all the parents 邀请所有家长。\n顺带记:拒绝 = refuse;离开 = leave;隐藏 = hide."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',6,NULL,'choice','{"stem":"scene 的意思是:","options":["掌声","(戏剧的)一场,场景","门票","观众"],"answer_index":1,"explanation_cn":"scene = (戏剧的)一场,场景。✓ the first scene will begin 第一场戏就要开始。\n顺带记:观众 = audience;掌声 = applause;门票 = ticket."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',7,NULL,'cloze','{"stem":"第 1 空","context":"Our class ___1___ put on a play next month. When the tickets ___2___ on sale, we ___3___ invite all the parents. Everyone thinks it ___4___ be a great show.","blank_no":1,"options":["is going to","is going","will going to","be going to"],"answer_index":0,"explanation_cn":"事先已定的计划,用 be going to + 原形。✓ Our class is going to put on a play.\n✗ is going:缺 to;✗ will going to:错;✗ be going to:缺 is。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',7,NULL,'cloze','{"stem":"第 2 空","context":"Our class ___1___ put on a play next month. When the tickets ___2___ on sale, we ___3___ invite all the parents. Everyone thinks it ___4___ be a great show.","blank_no":2,"options":["go","will go","are going","went"],"answer_index":0,"explanation_cn":"when 从句里用一般现在时表将来。✓ When the tickets go on sale…\n✗ will go:从句里不用 will;✗ are going:进行;✗ went:过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',7,NULL,'cloze','{"stem":"第 3 空","context":"Our class ___1___ put on a play next month. When the tickets ___2___ on sale, we ___3___ invite all the parents. Everyone thinks it ___4___ be a great show.","blank_no":3,"options":["will","are","do","were"],"answer_index":0,"explanation_cn":"主句表将来的决定,用 will + 原形。✓ we will invite all the parents.\n✗ are:与原形 invite 不搭;✗ do:一般现在;✗ were:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',7,NULL,'cloze','{"stem":"第 4 空","context":"Our class ___1___ put on a play next month. When the tickets ___2___ on sale, we ___3___ invite all the parents. Everyone thinks it ___4___ be a great show.","blank_no":4,"options":["will","is","was","has"],"answer_index":0,"explanation_cn":"对将来的预测,用 will + 原形。✓ it will be a great show.\n✗ is:一般现在;✗ was:过去;✗ has:与原形 be 不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',8,NULL,'choice','{"stem":"What is the class going to do next month?","options":["Put on a play","Clean the school","Take a test","Go on a trip"],"answer_index":0,"explanation_cn":"课文说 Our class is going to put on a play next month。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',8,NULL,'choice','{"stem":"What will they do if it rains on the day?","options":["Wait for another week","Sing outside anyway","Cancel the play","Move everything indoors"],"answer_index":3,"explanation_cn":"课文说 If it rains on the day, we will move everything indoors。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',8,NULL,'choice','{"stem":"When will the show start?","options":["At five","At nine","At seven","At noon"],"answer_index":2,"explanation_cn":"课文说 The show won''t start until seven。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',9,NULL,'choice','{"stem":"你想说\"我们班下个月要上演一出话剧\"(事先已定的计划,用 be going to):","options":["Our class is going to put on a play next month.","Our class going to put on a play next month.","Our class will putting on a play next month.","Our class is put on a play next month."],"answer_index":0,"explanation_cn":"事先已定的计划,用 be going to + 原形。✓ Our class is going to put on a play next month. 场合:说一件已经计划好的将来的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',9,NULL,'choice','{"stem":"你想说\"票开始出售时,我们会邀请家长\"(时间从句用现在时、主句用 will):","options":["When the tickets go on sale, we invite the parents.","When the tickets will be on sale, we inviting the parents.","When the tickets go on sale, we will invite the parents.","When the tickets will go on sale, we invite the parents."],"answer_index":2,"explanation_cn":"when 从句里用现在时表将来,主句用 will。✓ When the tickets go on sale, we will invite the parents. 场合:一件事发生时,就做另一件将来的事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',9,NULL,'choice','{"stem":"你想说\"看那乌云!要下雨了\"(根据迹象判断,用 be going to):","options":["Look at those clouds! It rained.","Look at those clouds! It rains.","Look at those clouds! It is raining soon.","Look at those clouds! It is going to rain."],"answer_index":3,"explanation_cn":"根据眼前迹象判断将要发生的事,用 be going to。✓ Look at those clouds! It is going to rain. 场合:有征兆时预判将来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"costume 的意思是:","options":["门票","戏服","灯光","布景"],"answer_index":1,"explanation_cn":"costume = 戏服、服装。✓ design the costumes 设计戏服。\n顺带记:门票 = ticket;布景 = background;灯光 = lights."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"invite 的意思是:","options":["出售","拒绝","忘记","邀请"],"answer_index":3,"explanation_cn":"invite = 邀请。✓ invite all the parents 邀请所有家长。\n顺带记:拒绝 = refuse;忘记 = forget;出售 = sell."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"\"Our class ___ put on a play next month.\"(事先已定的计划)","options":["is going to","will going to","is going","be going to"],"answer_index":0,"stem_cn":"我们班下个月要上演一出话剧。","explanation_cn":"事先已定的计划,用 be going to + 原形。✓ Our class is going to put on a play.\n✗ is going:缺 to;✗ will going to:错;✗ be going to:缺 is。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"\"When the tickets ___ on sale, we will invite them.\"(时间从句里表将来)","options":["went","will go","are going","go"],"answer_index":3,"stem_cn":"票开始出售时,我们会邀请他们。","explanation_cn":"when 从句里用一般现在时表将来。✓ When the tickets go on sale, we will invite them.\n✗ will go:从句里不用 will;✗ are going:进行;✗ went:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"\"put on a play\" 的意思是:","options":["穿上戏服","上演一出话剧","写一个剧本","放下一出戏"],"answer_index":1,"explanation_cn":"put on a play = 上演一出话剧(put on = 上演、演出)。✓ Our class is going to put on a play。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"\"be going to\" 常用来表示:","options":["过去的习惯","正在发生的事","事先已定的计划、打算","刚刚完成的动作"],"answer_index":2,"explanation_cn":"be going to 常用来表示事先已经定好的计划、打算,或根据迹象作出的判断。✓ Mia is going to design the costumes。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"Who is going to design the costumes?","options":["Mia","The teacher","Leo","Sam"],"answer_index":0,"passage":"Our class is going to put on a play next month. \"It will be a lot of work,\" the teacher said, \"but I''m sure it will be fun.\" When the tickets go on sale, we will invite all the parents. Mia is going to design the costumes, and Leo will paint the background. \"If it rains on the day, we will move everything indoors.\" \"Are you going to sing in the play?\" I asked Sam. \"Yes, I am. I am going to practice every evening this week.\" The show won''t start until seven, so we will have time to get ready. As soon as the lights go down, the first scene will begin. \"I think this is going to be the best play our school has ever seen!\"","explanation_cn":"课文说 Mia is going to design the costumes。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"Who will paint the background?","options":["The parents","Mia","Sam","Leo"],"answer_index":3,"passage":"Our class is going to put on a play next month. \"It will be a lot of work,\" the teacher said, \"but I''m sure it will be fun.\" When the tickets go on sale, we will invite all the parents. Mia is going to design the costumes, and Leo will paint the background. \"If it rains on the day, we will move everything indoors.\" \"Are you going to sing in the play?\" I asked Sam. \"Yes, I am. I am going to practice every evening this week.\" The show won''t start until seven, so we will have time to get ready. As soon as the lights go down, the first scene will begin. \"I think this is going to be the best play our school has ever seen!\"","explanation_cn":"课文说 Leo will paint the background。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"What is the class going to do next month?","options":["Put on a play","Go on a trip","Take a test","Clean the school"],"answer_index":0,"audio":"Our class is going to put on a play next month. \"It will be a lot of work,\" the teacher said, \"but I''m sure it will be fun.\" When the tickets go on sale, we will invite all the parents. Mia is going to design the costumes, and Leo will paint the background. \"If it rains on the day, we will move everything indoors.\" \"Are you going to sing in the play?\" I asked Sam. \"Yes, I am. I am going to practice every evening this week.\" The show won''t start until seven, so we will have time to get ready. As soon as the lights go down, the first scene will begin. \"I think this is going to be the best play our school has ever seen!\"","explanation_cn":"课文说 Our class is going to put on a play next month。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l84',10,NULL,'choice','{"stem":"What will they do if it rains on the day?","options":["Wait a week","Sing outside","Cancel the show","Move everything indoors"],"answer_index":3,"audio":"Our class is going to put on a play next month. \"It will be a lot of work,\" the teacher said, \"but I''m sure it will be fun.\" When the tickets go on sale, we will invite all the parents. Mia is going to design the costumes, and Leo will paint the background. \"If it rains on the day, we will move everything indoors.\" \"Are you going to sing in the play?\" I asked Sam. \"Yes, I am. I am going to practice every evening this week.\" The show won''t start until seven, so we will have time to get ready. As soon as the lights go down, the first scene will begin. \"I think this is going to be the best play our school has ever seen!\"","explanation_cn":"课文说 If it rains on the day, we will move everything indoors。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l85',2,11,85,'Never Too Old to Learn','活到老,学到老','复习 KS13/37/61 将来的各种时态(收官包·干净课照搬美语化):一般将来时 will do、将来进行时 will be doing、将来完成时 will have done、将来完成进行时 will have been doing 的构成与辨析,以及 by/in/at this time 等时间标志的搭配','下个月,我七十岁的爷爷就要上大学了。到明年这个时候,他就读完一年级了。“到我下个生日,我就整整学满一年了,”他自豪地说。开学那天,大家都会关注他表现如何。“有些人会笑话我,”他坦言,“但我不介意。五年后,我就能拿到学位了。”他会和比自己小六十岁的同学坐在同一间教室里。“学新东西,永远不嫌老,”他对我说。等他毕业时,他会证明所有人都想错了。我觉得,他会成为这所大学有史以来最鼓舞人心的学生。','{"q":"Listen and answer — What is the grandfather going to do next month?","options":["Start college at seventy","Retire from his job","Move to another city","Teach a math class"],"answer_index":0}'::jsonb,'{"title":"复习 KS13/37/61 将来的各种时态","intro":"本课把“将来”的四种时态放在一起复习:①一般将来 will do——单纯说将来会怎样(Some people will laugh);②将来进行 will be doing——将来某个时刻正在进行(This time tomorrow, he will be sitting in class);③将来完成 will have done——到将来某个时间点之前已经完成(By next year, he will have finished his first year);④将来完成进行 will have been doing——到将来某时为止一直持续(By my next birthday, I will have been studying for a year)。看时间标志选形式:by + 时间点 常配将来完成,at/this time + 时间点 常配将来进行,in + 一段时间 表“……之后”。","table":{"headers":["时态","例子"],"rows":[["一般将来 will do","Some people will laugh, but he doesn''t mind."],["将来进行 will be doing","This time tomorrow, he will be sitting in class."],["将来完成 will have done","By next year, he will have finished his first year."],["将来完成进行 will have been doing","By his birthday, he will have been studying for a year."]]},"specialRules":[{"rule":"美语“成绩、分数”说 grade(英式 mark);“数学”说 math(英式 maths)。本课已按美语写。","mark":"grade / math"},{"rule":"by + 时间点 → 将来完成(之前完成);at/this time + 时间点 → 将来进行(那一刻正在做);in + 一段时间 → “……之后”。","mark":"时间标志"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l85',1,NULL,'Next month, my grandfather will be starting college at the age of seventy. By this time next year, he will have finished his first year.','下个月,我七十岁的爷爷就要上大学了。到明年这个时候,他就读完一年级了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l85',2,NULL,'"By my next birthday, I will have been studying for a whole year," he says proudly. On the first day, everyone will be watching to see how he does.','“到我下个生日,我就整整学满一年了,”他自豪地说。开学那天,大家都会关注他表现如何。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l85',3,NULL,'"Some people will laugh," he admits, "but I don''t mind. In five years, I will have earned my degree."','“有些人会笑话我,”他坦言,“但我不介意。五年后,我就能拿到学位了。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l85',4,NULL,'He will be sitting in class with students sixty years younger. "You will never be too old to learn something new," he tells me.','他会和比自己小六十岁的同学坐在同一间教室里。“学新东西,永远不嫌老,”他对我说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l85',5,NULL,'By the time he graduates, he will have proved everyone wrong. I think he will be the most inspiring student the college has ever seen.','等他毕业时,他会证明所有人都想错了。我觉得,他会成为这所大学有史以来最鼓舞人心的学生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
