INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l85','go to college','',NULL,'/ɡoʊ tu ˈkɑːlɪdʒ/','He is going to college at the age of seventy.','他七十岁时去上大学。','She hopes to go to college next fall.','她希望明年秋天上大学。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l85','at the age of','',NULL,'/ət ði eɪdʒ əv/','He is starting college at the age of seventy.','他七十岁开始上大学。','She learned to swim at the age of five.','她五岁时学会了游泳。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l85','too old to','',NULL,'/tuː oʊld tu/','You will never be too old to learn.','学习永远不嫌老。','He is never too old to try new things.','他学新事物从不嫌老。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l85','earn a degree','',NULL,'/ɜːrn ə dɪˈɡriː/','In five years, he will have earned his degree.','五年后,他就拿到学位了。','She worked hard to earn a degree in science.','她努力攻读科学学位。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp1','choice','{"stem":"\"Some people ___,\" he admits, \"but I don''t mind.\"(单纯说将来会怎样)","options":["will laugh","laughed","have laughed","are laughing"],"answer_index":0,"stem_cn":"“有些人会笑话我,”他坦言,“但我不介意。”","explanation_cn":"单纯说将来会怎样,用一般将来时 will + 动词原形。✓ Some people will laugh. ✗ are laughing:现在进行;✗ laughed:过去;✗ have laughed:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp1','choice','{"stem":"\"You ___ too old to learn something new,\" he tells me.(一般将来的否定)","options":["are never","were never","will never be","have never been"],"answer_index":2,"stem_cn":"“学新东西,永远不嫌老,”他对我说。","explanation_cn":"一般将来的否定,把 never 放在 will 之后。✓ You will never be too old to learn. ✗ are never:一般现在;✗ were never:过去;✗ have never been:现在完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp1','choice','{"stem":"\"I think he ___ the most inspiring student the college has seen.\"(单纯对将来的判断)","options":["will be","has been","was","is being"],"answer_index":0,"stem_cn":"我觉得他会是这所大学最鼓舞人心的学生。","explanation_cn":"对将来的判断,用一般将来时。✓ He will be the most inspiring student. ✗ is being:现在进行;✗ was:过去;✗ has been:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp2','choice','{"stem":"\"At this time next month, grandfather ___ his first college classes.\"(将来某刻正在进行)","options":["took","is taking","will be taking","will take"],"answer_index":2,"stem_cn":"下个月的这个时候,爷爷正在上他的第一批大学课程。","explanation_cn":"将来某个时刻正在进行,用将来进行时 will be + doing。✓ At this time next month, he will be taking his first classes. ✗ will take:一般将来,不表“那一刻正在进行”;✗ is taking:现在进行;✗ took:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp2','choice','{"stem":"\"This time tomorrow, he ___ in class with younger students.\"(将来某刻正在进行)","options":["sat","will be sitting","is sitting","will sit"],"answer_index":1,"stem_cn":"明天这个时候,他正和更年轻的同学一起坐在教室里。","explanation_cn":"将来某刻正在进行,用将来进行时。✓ This time tomorrow, he will be sitting in class. ✗ will sit:一般将来;✗ is sitting:现在进行;✗ sat:过去。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp2','choice','{"stem":"\"Everyone ___ closely as he walks in on the first day.\"(将来某刻正在进行)","options":["has watched","watches","will be watching","watched"],"answer_index":2,"stem_cn":"开学第一天他走进来时,大家都在密切关注。","explanation_cn":"将来某刻正在进行,用将来进行时。✓ Everyone will be watching as he walks in. ✗ watches:一般现在;✗ watched:过去;✗ has watched:现在完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp3','choice','{"stem":"\"By this time next year, he ___ his first year.\"(将来某时点之前已完成)","options":["will have finished","finished","will finish","has finished"],"answer_index":0,"stem_cn":"到明年这个时候,他就读完一年级了。","explanation_cn":"到将来某个时间点之前已经完成,用将来完成时 will have + 过去分词。✓ By next year, he will have finished his first year. ✗ will finish:一般将来,不强调“之前已完成”;✗ has finished:现在完成;✗ finished:过去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp3','choice','{"stem":"\"In five years, I ___ my degree,\" he said.(将来某时点之前已完成)","options":["will earn","will have earned","earned","have earned"],"answer_index":1,"stem_cn":"“五年后,我就拿到学位了,”他说。","explanation_cn":"到将来某时点之前已完成,用将来完成时。✓ In five years, I will have earned my degree. ✗ will earn:一般将来;✗ have earned:现在完成;✗ earned:过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp3','choice','{"stem":"\"By the time he graduates, he ___ everyone wrong.\"(将来某时点之前已完成)","options":["will have proved","will prove","has proved","proved"],"answer_index":0,"stem_cn":"等他毕业时,他就证明了所有人都想错了。","explanation_cn":"到将来某时点之前已完成,用将来完成时。✓ By the time he graduates, he will have proved everyone wrong. ✗ will prove:一般将来;✗ has proved:现在完成;✗ proved:过去。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp4','choice','{"stem":"\"By my next birthday, I ___ for a whole year,\" he says.(到将来某时为止一直持续)","options":["studied","will have been studying","have been studying","will study"],"answer_index":1,"stem_cn":"“到我下个生日,我就整整学满一年了,”他说。","explanation_cn":"到将来某时为止一直持续,用将来完成进行时 will have been + doing。✓ By my next birthday, I will have been studying for a whole year. ✗ will study:一般将来;✗ have been studying:现在完成进行;✗ studied:过去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp4','choice','{"stem":"\"By June, he ___ English every day for six months.\"(到将来某时为止一直持续)","options":["learned","will learn","has been learning","will have been learning"],"answer_index":3,"stem_cn":"到六月,他就每天学英语学满六个月了。","explanation_cn":"到将来某时为止一直持续,用将来完成进行时。✓ By June, he will have been learning English for six months. ✗ will learn:一般将来;✗ has been learning:现在完成进行;✗ learned:过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp4','choice','{"stem":"\"By the time the course ends, he ___ hard for a full year.\"(到将来某时为止一直持续)","options":["worked","will have been working","will work","has worked"],"answer_index":1,"stem_cn":"到课程结束时,他就刻苦学习满整整一年了。","explanation_cn":"到将来某时为止一直持续,用将来完成进行时。✓ By the time the course ends, he will have been working hard for a year. ✗ will work:一般将来;✗ has worked:现在完成;✗ worked:过去。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp5','choice','{"stem":"\"___ five years, I will have earned my degree.\"(表示“……之后”用哪个词)","options":["For","Since","By","In"],"answer_index":3,"stem_cn":"五年后,我就拿到学位了。","explanation_cn":"“……之后”用 in + 一段时间。✓ In five years, I will have earned my degree. ✗ By:到……为止(接时间点);✗ Since:自从(接起点);✗ For:持续(接时间长度)。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp5','choice','{"stem":"\"___ the time he graduates, he will have proved everyone wrong.\"(引出“将来某时点”的词)","options":["For","In","By","On"],"answer_index":2,"stem_cn":"等他毕业时,他就证明了所有人都想错了。","explanation_cn":"引出“将来某个时间点”用 by。✓ By the time he graduates, he will have proved everyone wrong. ✗ In:“……之后”;✗ On:接具体日子；✗ For:接时间长度。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp5','choice','{"stem":"\"At this time next month, grandfather ___ college.\"(与“at this time next month”搭配)","options":["will have started","starts","started","will be starting"],"answer_index":3,"stem_cn":"下个月这个时候,爷爷正在上大学。","explanation_cn":"与“at this time next month”这样的时间点搭配,表示那一刻正在进行,用将来进行时。✓ At this time next month, he will be starting college. ✗ will have started:将来完成,表“之前已完成”,与“那一刻正在进行”不符;✗ starts:一般现在;✗ started:过去。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp6','choice','{"stem":"\"He is going back to school to earn a college ___.\"(学位用哪个词)","options":["ticket","seat","degree","prize"],"answer_index":2,"stem_cn":"他重返校园去攻读大学学位。","explanation_cn":"大学“学位”是 degree。✓ earn a college degree. ✗ ticket:门票;✗ prize:奖品;✗ seat:座位。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp6','choice','{"stem":"\"''Some people will laugh,'' he ___, ''but I don''t mind.''\"(坦言、承认用哪个词)","options":["forgets","admits","hides","refuses"],"answer_index":1,"stem_cn":"“有些人会笑话我,”他坦言,“但我不介意。”","explanation_cn":"“坦言、承认”是 admit(第三人称 admits)。✓ he admits. ✗ refuses:拒绝;✗ forgets:忘记;✗ hides:隐藏。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',5,'am2_l85_gp6','choice','{"stem":"\"He will be the most ___ student the college has seen.\"(鼓舞人心的用哪个词)","options":["inspiring","lazy","boring","angry"],"answer_index":0,"stem_cn":"他会是这所大学见过的最鼓舞人心的学生。","explanation_cn":"“鼓舞人心的”是 inspiring。✓ the most inspiring student. ✗ boring:无聊的;✗ lazy:懒惰的;✗ angry:生气的。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"美语里\"成绩、分数\"说:","options":["point","note","grade","mark"],"answer_index":2,"explanation_cn":"美语“成绩、分数”说 grade;英式说 mark。✓ He got a top grade in math. 他数学得了最高分。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"美语里\"数学\"说:","options":["count","maths","number","math"],"answer_index":3,"explanation_cn":"美语“数学”说 math;英式说 maths。✓ Math is his favorite subject. 数学是他最喜欢的科目。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"degree 的意思是:","options":["学位","门票","奖品","座位"],"answer_index":0,"explanation_cn":"degree = 学位。✓ earn my degree 拿到我的学位。\n顺带记:门票 = ticket;奖品 = prize;座位 = seat."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"admit 的意思是:","options":["隐藏","承认,坦言","忘记","拒绝"],"answer_index":1,"explanation_cn":"admit = 承认、坦言。✓ \"Some people will laugh,\" he admits 他坦言有些人会笑话他。\n顺带记:拒绝 = refuse;忘记 = forget;隐藏 = hide."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"inspiring 的意思是:","options":["生气的","懒惰的","鼓舞人心的","无聊的"],"answer_index":2,"explanation_cn":"inspiring = 鼓舞人心的。✓ the most inspiring student 最鼓舞人心的学生。\n顺带记:无聊的 = boring;懒惰的 = lazy;生气的 = angry."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',6,NULL,'choice','{"stem":"graduate 的意思是:","options":["逃学","退学","入学","毕业"],"answer_index":3,"explanation_cn":"graduate = 毕业。✓ by the time he graduates 等他毕业时。\n顺带记:入学 = enroll;退学 = drop out;逃学 = skip school."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',7,NULL,'cloze','{"stem":"第 1 空","context":"Next month, grandfather ___1___ college at seventy. By this time next year, he ___2___ his first year. In five years, he ___3___ his degree. He ___4___ never be too old to learn.","blank_no":1,"options":["will be starting","will have started","starts","started"],"answer_index":0,"explanation_cn":"将来某段时间正在进行,用将来进行时。✓ Next month, grandfather will be starting college.\n✗ will have started:将来完成;✗ starts:一般现在;✗ started:过去。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',7,NULL,'cloze','{"stem":"第 2 空","context":"Next month, grandfather ___1___ college at seventy. By this time next year, he ___2___ his first year. In five years, he ___3___ his degree. He ___4___ never be too old to learn.","blank_no":2,"options":["will have finished","will finish","has finished","finished"],"answer_index":0,"explanation_cn":"到将来某时点之前已完成,用将来完成时。✓ By next year, he will have finished his first year.\n✗ will finish:一般将来;✗ has finished:现在完成;✗ finished:过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',7,NULL,'cloze','{"stem":"第 3 空","context":"Next month, grandfather ___1___ college at seventy. By this time next year, he ___2___ his first year. In five years, he ___3___ his degree. He ___4___ never be too old to learn.","blank_no":3,"options":["will have earned","will earn","has earned","earned"],"answer_index":0,"explanation_cn":"到将来某时点之前已完成,用将来完成时。✓ In five years, he will have earned his degree.\n✗ will earn:一般将来;✗ has earned:现在完成;✗ earned:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',7,NULL,'cloze','{"stem":"第 4 空","context":"Next month, grandfather ___1___ college at seventy. By this time next year, he ___2___ his first year. In five years, he ___3___ his degree. He ___4___ never be too old to learn.","blank_no":4,"options":["will","is","was","has"],"answer_index":0,"explanation_cn":"单纯说将来,用一般将来时 will + 原形。✓ He will never be too old to learn.\n✗ is:一般现在;✗ was:过去;✗ has:与原形 be 不搭。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',8,NULL,'choice','{"stem":"How old is the grandfather when he starts college?","options":["Seventeen","Seventy","Eighty","Sixty"],"answer_index":1,"explanation_cn":"课文说 my grandfather will be starting college at the age of seventy。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',8,NULL,'choice','{"stem":"What does he say some people will do?","options":["Go with him","Stop him","Laugh at him","Help him study"],"answer_index":2,"explanation_cn":"课文说 \"Some people will laugh,\" he admits——即有些人会笑话他。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',8,NULL,'choice','{"stem":"How does the writer describe the grandfather?","options":["The most inspiring student the college has seen","A lazy student","A shy young boy","The oldest teacher in town"],"answer_index":0,"explanation_cn":"课文说 I think he will be the most inspiring student the college has ever seen。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',9,NULL,'choice','{"stem":"你想说\"到明年这时候,他就读完一年级了\"(将来某时前已完成,用 will have done):","options":["By this time next year, he finishes his first year.","By this time next year, he will finish his first year.","By this time next year, he will have finished his first year.","By this time next year, he has finished his first year."],"answer_index":2,"explanation_cn":"到将来某时点之前已完成,用将来完成时 will have + 过去分词。✓ By this time next year, he will have finished his first year. 场合:说到将来某时点某事已经做完。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',9,NULL,'choice','{"stem":"你想说\"明天这时候,他正坐在教室里\"(将来某刻正在进行,用 will be doing):","options":["This time tomorrow, he sits in class.","This time tomorrow, he will be sitting in class.","This time tomorrow, he is sitting in class.","This time tomorrow, he will sit in class."],"answer_index":1,"explanation_cn":"将来某刻正在进行,用将来进行时 will be + doing。✓ This time tomorrow, he will be sitting in class. 场合:说将来某个时刻正在做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',9,NULL,'choice','{"stem":"你想说\"到下次生日,我就学满一整年了\"(到将来某时持续,用 will have been doing):","options":["By my next birthday, I will study for a whole year.","By my next birthday, I have been studying for a whole year.","By my next birthday, I am studying for a whole year.","By my next birthday, I will have been studying for a whole year."],"answer_index":3,"explanation_cn":"到将来某时为止一直持续,用将来完成进行时 will have been + doing。✓ By my next birthday, I will have been studying for a whole year. 场合:强调某动作持续到将来某时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"degree 的意思是:","options":["学位","门票","座位","奖品"],"answer_index":0,"explanation_cn":"degree = 学位。✓ earn my degree 拿到学位。\n顺带记:门票 = ticket;奖品 = prize;座位 = seat."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"admit 的意思是:","options":["出售","忘记","承认,坦言","拒绝"],"answer_index":2,"explanation_cn":"admit = 承认、坦言。✓ he admits 他坦言。\n顺带记:拒绝 = refuse;忘记 = forget;出售 = sell."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"\"By this time next year, he ___ his first year.\"(将来某时前已完成)","options":["has finished","will finish","finished","will have finished"],"answer_index":3,"stem_cn":"到明年这个时候,他就读完一年级了。","explanation_cn":"到将来某时点之前已完成,用将来完成时。✓ By next year, he will have finished his first year.\n✗ will finish:一般将来;✗ has finished:现在完成;✗ finished:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"\"This time tomorrow, he ___ in class.\"(将来某刻正在进行)","options":["sat","is sitting","will be sitting","will sit"],"answer_index":2,"stem_cn":"明天这个时候,他正坐在教室里。","explanation_cn":"将来某刻正在进行,用将来进行时。✓ This time tomorrow, he will be sitting in class.\n✗ will sit:一般将来;✗ is sitting:现在进行;✗ sat:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"\"too old to learn\" 的意思是:","options":["老学生","年纪太大而学不了新东西","老了以后才学习","学得年纪太大"],"answer_index":1,"explanation_cn":"too old to learn = 年纪太大而学不了(too…to… 表“太……以致不能”)。这里强调其实永远不嫌老。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"\"earn a degree\" 的意思是:","options":["得一个名次","拿一张票","取得学位","赚一笔钱"],"answer_index":2,"explanation_cn":"earn a degree = 取得学位(earn 在这里是“获得、挣得”)。✓ In five years, he will have earned his degree。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"What is the grandfather going to do next month?","options":["Retire and rest","Start college at seventy","Move to a new town","Teach a class"],"answer_index":1,"passage":"Next month, my grandfather will be starting college at the age of seventy. By this time next year, he will have finished his first year. \"By my next birthday, I will have been studying for a whole year,\" he says proudly. On the first day, everyone will be watching to see how he does. \"Some people will laugh,\" he admits, \"but I don''t mind. In five years, I will have earned my degree.\" He will be sitting in class with students sixty years younger. \"You will never be too old to learn something new,\" he tells me. By the time he graduates, he will have proved everyone wrong. I think he will be the most inspiring student the college has ever seen.","explanation_cn":"课文说 Next month, my grandfather will be starting college at the age of seventy。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"In five years, what will the grandfather have earned?","options":["A new car","A gold medal","A lot of money","His college degree"],"answer_index":3,"passage":"Next month, my grandfather will be starting college at the age of seventy. By this time next year, he will have finished his first year. \"By my next birthday, I will have been studying for a whole year,\" he says proudly. On the first day, everyone will be watching to see how he does. \"Some people will laugh,\" he admits, \"but I don''t mind. In five years, I will have earned my degree.\" He will be sitting in class with students sixty years younger. \"You will never be too old to learn something new,\" he tells me. By the time he graduates, he will have proved everyone wrong. I think he will be the most inspiring student the college has ever seen.","explanation_cn":"课文说 In five years, I will have earned my degree。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"What does the grandfather say some people will do?","options":["Laugh at him","Join him","Help him","Stop him"],"answer_index":0,"audio":"Next month, my grandfather will be starting college at the age of seventy. By this time next year, he will have finished his first year. \"By my next birthday, I will have been studying for a whole year,\" he says proudly. On the first day, everyone will be watching to see how he does. \"Some people will laugh,\" he admits, \"but I don''t mind. In five years, I will have earned my degree.\" He will be sitting in class with students sixty years younger. \"You will never be too old to learn something new,\" he tells me. By the time he graduates, he will have proved everyone wrong. I think he will be the most inspiring student the college has ever seen.","explanation_cn":"课文说 \"Some people will laugh,\" he admits。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l85',10,NULL,'choice','{"stem":"How is the grandfather described at the end?","options":["A very shy boy","The most inspiring student","An angry old man","The laziest student"],"answer_index":1,"audio":"Next month, my grandfather will be starting college at the age of seventy. By this time next year, he will have finished his first year. \"By my next birthday, I will have been studying for a whole year,\" he says proudly. On the first day, everyone will be watching to see how he does. \"Some people will laugh,\" he admits, \"but I don''t mind. In five years, I will have earned my degree.\" He will be sitting in class with students sixty years younger. \"You will never be too old to learn something new,\" he tells me. By the time he graduates, he will have proved everyone wrong. I think he will be the most inspiring student the college has ever seen.","explanation_cn":"课文说 he will be the most inspiring student the college has ever seen。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l86',2,11,86,'The Runaway Kite','跑掉的风筝','复习 KS14/38/62 过去完成时 vs 过去完成进行时(方案B换情节包):had done(过去的过去、已完成)与 had been doing(持续到过去某点)的构成与辨析,以及与 before/after/when/by the time 的搭配,后发生的动作用一般过去时','等我们到公园时,风已经变得很强了。我们盼着放这只新风筝盼了一整周。风筝是里奥自己做的,他还给它上了两天的色。我们还没开始,风就把风筝从他手里扯走了。风筝才飞高了一分钟,线就断了。我们还没来得及去抓,风筝已经飞过树梢不见了。我们到处找,可它早已落在了远处的一片田野里。一个小女孩捡到了它,一直小心地抱着。她一直在等有人回来找它。等我们到家时,我们已经交到了一个新朋友——也学会了要抓得更紧!','{"q":"Listen and answer — What happened when the kite''s string broke?","options":["The kite flew away over the trees","The kite fell straight down","Leo caught the kite at once","Nothing happened at all"],"answer_index":0}'::jsonb,'{"title":"复习 KS14/38/62 过去完成 vs 过去完成进行","intro":"本课复习“过去的过去”两种时态及其区别:①过去完成 had done——在过去某个时间点之前已经完成的动作(By the time we reached the park, the wind had grown strong);②过去完成进行 had been doing——持续到过去某个时间点的动作,强调“一直在做”(We had been looking forward to it all week);③二者对比:强调“已完成/结果”用 had done,强调“持续过程”用 had been doing;④常配 before / after / when / by the time,后发生的那个动作用一般过去时(…before the string broke)。","table":{"headers":["时态","例子"],"rows":[["过去完成 had done","By the time we arrived, the wind had grown strong."],["过去完成进行 had been doing","We had been looking forward to it all week."],["对比","It had been flying (过程) … had disappeared (结果)."],["后发生的动作用一般过去","It had been flying for a minute when the string broke."]]},"specialRules":[{"rule":"美语“足球”说 soccer(英式 football);“运动鞋”说 sneakers(英式 trainers)。本课已按美语写。","mark":"soccer / sneakers"},{"rule":"过去完成看“过去某点之前是否已完成”,过去完成进行强调“持续到那个点”;两件事里先发生的用过去完成,后发生的用一般过去。","mark":"时态辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l86',1,NULL,'By the time we reached the park, the wind had already grown strong. We had been looking forward to flying our new kite all week.','等我们到公园时,风已经变得很强了。我们盼着放这只新风筝盼了一整周。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l86',2,NULL,'Leo had built it himself, and he had been painting it for two days. Before we even started, the wind had pulled the kite from his hands.','风筝是里奥自己做的,他还给它上了两天的色。我们还没开始,风就把风筝从他手里扯走了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l86',3,NULL,'It had been flying high for only a minute when the string broke. The kite had disappeared over the trees before we could catch it.','风筝才飞高了一分钟,线就断了。我们还没来得及去抓,风筝已经飞过树梢不见了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l86',4,NULL,'We searched everywhere, but it had already landed in a far field. A little girl had found it and had been holding it carefully.','我们到处找,可它早已落在了远处的一片田野里。一个小女孩捡到了它,一直小心地抱着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l86',5,NULL,'She had been waiting for someone to come back for it. By the time we got home, we had made a new friend — and learned to hold on tighter!','她一直在等有人回来找它。等我们到家时,我们已经交到了一个新朋友——也学会了要抓得更紧!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
