INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l86','look forward to','',NULL,'/lʊk ˈfɔːrwərd tu/','We had been looking forward to it all week.','我们盼这件事盼了一整周。','I look forward to seeing you again.','我期待再见到你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l86','by the time','',NULL,'/baɪ ðə taɪm/','By the time we reached the park, the wind had grown strong.','等我们到公园时,风已经变强了。','By the time she called, we had left.','她打电话时,我们已经走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l86','hold on','',NULL,'/hoʊld ɑːn/','We learned to hold on tighter.','我们学会了抓得更紧。','Hold on to the rope with both hands.','双手抓紧绳子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l86','fly a kite','',NULL,'/flaɪ ə kaɪt/','We had been looking forward to flying our new kite.','我们一直盼着放新风筝。','It''s a windy day — let''s fly a kite.','今天风大——我们去放风筝吧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp1','choice','{"stem":"\"By the time we reached the park, the wind ___ strong.\"(过去某时之前已经变强)","options":["grew","has grown","was growing","had grown"],"answer_index":3,"stem_cn":"等我们到公园时,风已经变强了。","explanation_cn":"在过去某个时间点之前已经完成,用过去完成时 had + 过去分词。✓ By the time we reached the park, the wind had grown strong. ✗ grew:一般过去,不表“之前已完成”;✗ has grown:现在完成;✗ was growing:过去进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp1','choice','{"stem":"\"Before we even started, the wind ___ the kite from his hands.\"(在开始之前就已经)","options":["pulled","has pulled","had pulled","was pulling"],"answer_index":2,"stem_cn":"我们还没开始,风就已经把风筝从他手里扯走了。","explanation_cn":"“在开始之前就已经”发生,用过去完成时。✓ Before we started, the wind had pulled the kite away. ✗ pulled:一般过去;✗ has pulled:现在完成;✗ was pulling:过去进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp1','choice','{"stem":"\"We searched everywhere, but the kite ___ in a far field.\"(此前已经落下)","options":["has landed","had landed","was landing","landed"],"answer_index":1,"stem_cn":"我们到处找,但风筝早已落在远处的田野里。","explanation_cn":"“我们找之前它早已落下”,用过去完成时。✓ It had already landed in a far field. ✗ landed:一般过去;✗ has landed:现在完成;✗ was landing:过去进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp2','choice','{"stem":"\"We ___ to flying our new kite all week.\"(持续到过去某点)","options":["were looking forward","looked forward","had been looking forward","have looked forward"],"answer_index":2,"stem_cn":"我们盼着放新风筝盼了一整周。","explanation_cn":"持续到过去某点、强调“一直在盼”,用过去完成进行时 had been + doing。✓ We had been looking forward to it all week. ✗ looked forward:一般过去;✗ have looked forward:现在完成;✗ were looking forward:过去进行,不强调“持续到那点”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp2','choice','{"stem":"\"Leo ___ the kite for two days before the trip.\"(持续到过去某点)","options":["painted","was painting","has painted","had been painting"],"answer_index":3,"stem_cn":"出发前,里奥已经给风筝上了两天的色。","explanation_cn":"持续到过去某点,用过去完成进行时。✓ He had been painting the kite for two days. ✗ painted:一般过去;✗ has painted:现在完成;✗ was painting:过去进行。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp2','choice','{"stem":"\"A little girl ___ the kite carefully when we found her.\"(持续到过去某点)","options":["had been holding","has held","holds","held"],"answer_index":0,"stem_cn":"我们找到她时,小女孩一直小心地抱着风筝。","explanation_cn":"持续到过去某点(我们找到她时),用过去完成进行时。✓ She had been holding the kite carefully. ✗ held:一般过去;✗ has held:现在完成;✗ holds:一般现在。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp3','choice','{"stem":"\"It ___ high for a minute when the string broke.\"(强调持续了一分钟)","options":["flies","flew","had flown","had been flying"],"answer_index":3,"stem_cn":"风筝才飞高了一分钟,线就断了。","explanation_cn":"强调“飞了一分钟”这个持续过程,用过去完成进行时。✓ It had been flying high for a minute when the string broke. ✗ had flown:过去完成,只说完成不强调过程;✗ flew:一般过去;✗ flies:一般现在。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp3','choice','{"stem":"\"By the time we got home, we ___ a new friend.\"(强调已完成的结果)","options":["made","had been making","had made","make"],"answer_index":2,"stem_cn":"等我们到家时,我们已经交到一个新朋友。","explanation_cn":"强调“已经交到新朋友”这个结果,用过去完成时。✓ By the time we got home, we had made a new friend. ✗ had been making:强调过程,与“已交到”不符;✗ made:一般过去;✗ make:一般现在。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp3','choice','{"stem":"\"She ___ for someone to come back for it.\"(强调一直在等)","options":["waited","had been waiting","had waited","waits"],"answer_index":1,"stem_cn":"她一直在等有人回来找它。","explanation_cn":"强调“一直在等”这个持续过程,用过去完成进行时。✓ She had been waiting for someone to come back. ✗ had waited:只说完成;✗ waited:一般过去;✗ waits:一般现在。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp4','choice','{"stem":"\"___ we reached the park, the wind had grown strong.\"(引出“过去某个时间点”)","options":["Since","For","During","By the time"],"answer_index":3,"stem_cn":"等我们到公园时,风已经变强了。","explanation_cn":"By the time 引出“过去某个时间点”,主句常配过去完成。✓ By the time we reached the park, the wind had grown strong. ✗ Since:自从(接起点);✗ For:接时间长度;✗ During:在……期间(接名词)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp4','choice','{"stem":"\"The kite had disappeared ___ we could catch it.\"(在……之前)","options":["since","before","during","so"],"answer_index":1,"stem_cn":"我们还没来得及抓,风筝就已经不见了。","explanation_cn":"“在……之前”用 before,前一动作用过去完成。✓ The kite had disappeared before we could catch it. ✗ since:自从;✗ during:在……期间;✗ so:因此。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp4','choice','{"stem":"\"___ we even started, the wind had pulled the kite away.\"(在……之前)","options":["Since","After","Before","While"],"answer_index":2,"stem_cn":"我们还没开始,风就已经把风筝扯走了。","explanation_cn":"“在……之前”用 before。✓ Before we even started, the wind had pulled the kite away. ✗ After:在……之后;✗ Since:自从;✗ While:当……的时候。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp5','choice','{"stem":"\"It had been flying high when the string ___.\"(后发生的动作用一般过去)","options":["broke","breaks","had broken","has broken"],"answer_index":0,"stem_cn":"风筝正飞得高高的,线断了。","explanation_cn":"两件事里后发生的那个动作,用一般过去时。✓ It had been flying high when the string broke. ✗ had broken:过去完成,应留给先发生的动作;✗ breaks:一般现在;✗ has broken:现在完成。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp5','choice','{"stem":"\"By the time we ___ home, we had made a new friend.\"(时间从句用一般过去)","options":["have got","got","had got","get"],"answer_index":1,"stem_cn":"等我们到家时,已经交到一个新朋友。","explanation_cn":"by the time 引导的时间从句里,用一般过去时;主句才用过去完成。✓ By the time we got home, we had made a new friend. ✗ had got:从句里不用过去完成;✗ get:一般现在;✗ have got:现在完成。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp5','choice','{"stem":"\"The kite had disappeared before we ___ catch it.\"(后一动作用一般过去)","options":["could","will","can","had could"],"answer_index":0,"stem_cn":"我们还没来得及抓,风筝就不见了。","explanation_cn":"后发生、能否赶上的那个动作,用一般过去(could)。✓ The kite had disappeared before we could catch it. ✗ had could:无此形式;✗ can:一般现在;✗ will:将来。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp6','choice','{"stem":"\"The kite flew away when the ___ broke.\"(线、绳用哪个词)","options":["chair","plate","string","window"],"answer_index":2,"stem_cn":"线一断,风筝就飞走了。","explanation_cn":"风筝的“线、绳”是 string。✓ the string broke. ✗ chair:椅子;✗ window:窗户;✗ plate:盘子。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp6','choice','{"stem":"\"We ___ everywhere for the lost kite.\"(到处寻找用哪个词)","options":["cooked","searched","sang","slept"],"answer_index":1,"stem_cn":"我们到处寻找丢失的风筝。","explanation_cn":"“到处寻找”是 search(过去式 searched)。✓ We searched everywhere. ✗ cooked:做饭;✗ slept:睡觉;✗ sang:唱歌。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',5,'am2_l86_gp6','choice','{"stem":"\"The kite had landed in a far ___.\"(田野用哪个词)","options":["field","book","kitchen","pocket"],"answer_index":0,"stem_cn":"风筝落在了远处的一片田野里。","explanation_cn":"“田野、场地”是 field。✓ landed in a far field. ✗ kitchen:厨房;✗ pocket:口袋;✗ book:书。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"美语里\"足球\"说:","options":["soccer","kickball","ball-game","football"],"answer_index":0,"explanation_cn":"美语“足球”说 soccer;英式说 football。✓ They played soccer in the park. 他们在公园踢足球。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"美语里\"运动鞋\"说:","options":["gym-shoes","sneakers","trainers","runners"],"answer_index":1,"explanation_cn":"美语“运动鞋”说 sneakers;英式说 trainers。✓ He wore his new sneakers. 他穿着新运动鞋。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"string 的意思是:","options":["石头","云","树","线,绳"],"answer_index":3,"explanation_cn":"string = 线、绳。✓ the string broke 线断了。\n顺带记:树 = tree;石头 = stone;云 = cloud."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"disappear 的意思是:","options":["停下","落下","消失,不见","出现"],"answer_index":2,"explanation_cn":"disappear = 消失、不见。✓ the kite had disappeared 风筝不见了。\n顺带记:出现 = appear;停下 = stop;落下 = fall."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"field 的意思是:","options":["商店","田野,场地","卧室","厨房"],"answer_index":1,"explanation_cn":"field = 田野、场地。✓ landed in a far field 落在远处的田野里。\n顺带记:厨房 = kitchen;卧室 = bedroom;商店 = store."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',6,NULL,'choice','{"stem":"search 的意思是:","options":["搜寻,寻找","购买","忘记","出售"],"answer_index":0,"explanation_cn":"search = 搜寻、寻找。✓ we searched everywhere 我们到处找。\n顺带记:购买 = buy;出售 = sell;忘记 = forget."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',7,NULL,'cloze','{"stem":"第 1 空","context":"By the time we reached the park, the wind ___1___ already grown strong. We ___2___ looking forward to it all week. The kite ___3___ high for a minute when the string ___4___.","blank_no":1,"options":["had","has","was","have"],"answer_index":0,"explanation_cn":"在过去某点之前已完成,用过去完成 had + 过去分词。✓ the wind had already grown strong.\n✗ has:现在完成;✗ was:过去进行;✗ have:主语单数不搭。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',7,NULL,'cloze','{"stem":"第 2 空","context":"By the time we reached the park, the wind ___1___ already grown strong. We ___2___ looking forward to it all week. The kite ___3___ high for a minute when the string ___4___.","blank_no":2,"options":["had been","have been","were","are"],"answer_index":0,"explanation_cn":"持续到过去某点,用过去完成进行 had been + doing。✓ We had been looking forward to it all week.\n✗ have been:现在完成进行;✗ were:过去进行;✗ are:一般现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',7,NULL,'cloze','{"stem":"第 3 空","context":"By the time we reached the park, the wind ___1___ already grown strong. We ___2___ looking forward to it all week. The kite ___3___ high for a minute when the string ___4___.","blank_no":3,"options":["had been flying","had flown","flew","flies"],"answer_index":0,"explanation_cn":"强调持续了一分钟,用过去完成进行时。✓ The kite had been flying high for a minute.\n✗ had flown:只说完成;✗ flew:一般过去;✗ flies:一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',7,NULL,'cloze','{"stem":"第 4 空","context":"By the time we reached the park, the wind ___1___ already grown strong. We ___2___ looking forward to it all week. The kite ___3___ high for a minute when the string ___4___.","blank_no":4,"options":["broke","had broken","breaks","has broken"],"answer_index":0,"explanation_cn":"后发生的动作用一般过去时。✓ …when the string broke.\n✗ had broken:应留给先发生的动作;✗ breaks:一般现在;✗ has broken:现在完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',8,NULL,'choice','{"stem":"What had happened to the wind by the time they reached the park?","options":["It had grown strong","It had turned warm","It had died down","It had stopped"],"answer_index":0,"explanation_cn":"课文说 By the time we reached the park, the wind had already grown strong。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',8,NULL,'choice','{"stem":"What happened when the string broke?","options":["The kite tore in two","The kite flew away over the trees","The kite fell straight down","Leo caught it at once"],"answer_index":1,"explanation_cn":"课文说 the string broke… The kite had disappeared over the trees——即风筝飞过树梢不见了。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',8,NULL,'choice','{"stem":"Who found the kite in the end?","options":["A dog","A farmer","A little girl","Their teacher"],"answer_index":2,"explanation_cn":"课文说 A little girl had found it and had been holding it carefully。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',9,NULL,'choice','{"stem":"你想说\"我们到公园时,风已经变强了\"(过去的过去,用 had done):","options":["By the time we reached the park, the wind was growing strong.","By the time we reached the park, the wind has grown strong.","By the time we reached the park, the wind grew strong.","By the time we reached the park, the wind had grown strong."],"answer_index":3,"explanation_cn":"在过去某点之前已完成,用过去完成 had + 过去分词。✓ By the time we reached the park, the wind had grown strong. 场合:说到过去某时点某事已经发生。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',9,NULL,'choice','{"stem":"你想说\"我们已经期待放新风筝一整周了\"(持续到过去某点,用 had been doing):","options":["We had been looking forward to flying our new kite all week.","We looked forward to flying our new kite all week.","We have been looking forward to flying our new kite all week.","We are looking forward to flying our new kite all week."],"answer_index":0,"explanation_cn":"持续到过去某点,用过去完成进行 had been + doing。✓ We had been looking forward to flying our new kite all week. 场合:强调某动作一直持续到过去某时。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',9,NULL,'choice','{"stem":"你想说\"风筝飞了一分钟,线就断了\"(先持续、后一般过去):","options":["The kite had been flying for a minute when the string had broken.","The kite was flying for a minute when the string breaks.","The kite had been flying for a minute when the string broke.","The kite has been flying for a minute when the string broke."],"answer_index":2,"explanation_cn":"先发生、持续的动作用过去完成进行,后发生的动作用一般过去。✓ The kite had been flying for a minute when the string broke. 场合:两件事,一件在进行,另一件突然发生。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"string 的意思是:","options":["树","云","石头","线,绳"],"answer_index":3,"explanation_cn":"string = 线、绳。✓ the string broke 线断了。\n顺带记:树 = tree;石头 = stone;云 = cloud."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"field 的意思是:","options":["卧室","田野,场地","商店","厨房"],"answer_index":1,"explanation_cn":"field = 田野、场地。✓ landed in a far field 落在远处的田野里。\n顺带记:厨房 = kitchen;卧室 = bedroom;商店 = store."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"\"By the time we reached the park, the wind ___ grown strong.\"(过去完成)","options":["have","was","has","had"],"answer_index":3,"stem_cn":"等我们到公园时,风已经变强了。","explanation_cn":"在过去某点之前已完成,用过去完成 had + 过去分词。✓ the wind had grown strong.\n✗ has:现在完成;✗ was:过去进行;✗ have:主语单数不搭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"\"She ___ for someone to come back for it.\"(过去完成进行)","options":["waits","waited","had been waiting","had waited"],"answer_index":2,"stem_cn":"她一直在等有人回来找它。","explanation_cn":"强调一直在等,用过去完成进行时。✓ She had been waiting for someone to come back.\n✗ had waited:只说完成;✗ waited:一般过去;✗ waits:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"\"look forward to\" 的意思是:","options":["抬头看","回头看","向前看路","期待,盼望"],"answer_index":3,"explanation_cn":"look forward to = 期待、盼望(to 后接名词或动名词)。✓ We had been looking forward to it all week。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"\"by the time\" 的意思是:","options":["偶尔地","花时间","到……的时候(为止)","按时地"],"answer_index":2,"explanation_cn":"by the time = 到……的时候(为止),引出一个时间点,主句常配过去完成。✓ By the time we got home, we had made a new friend。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"What had Leo done with the kite before the trip?","options":["He had borrowed it","He had built it himself","He had bought it in a store","He had broken it"],"answer_index":1,"passage":"By the time we reached the park, the wind had already grown strong. We had been looking forward to flying our new kite all week. Leo had built it himself, and he had been painting it for two days. Before we even started, the wind had pulled the kite from his hands. It had been flying high for only a minute when the string broke. The kite had disappeared over the trees before we could catch it. We searched everywhere, but it had already landed in a far field. A little girl had found it and had been holding it carefully. She had been waiting for someone to come back for it. By the time we got home, we had made a new friend — and learned to hold on tighter!","explanation_cn":"课文说 Leo had built it himself。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"Where had the kite landed?","options":["In a far field","On a tall tree","On the roof","In the river"],"answer_index":0,"passage":"By the time we reached the park, the wind had already grown strong. We had been looking forward to flying our new kite all week. Leo had built it himself, and he had been painting it for two days. Before we even started, the wind had pulled the kite from his hands. It had been flying high for only a minute when the string broke. The kite had disappeared over the trees before we could catch it. We searched everywhere, but it had already landed in a far field. A little girl had found it and had been holding it carefully. She had been waiting for someone to come back for it. By the time we got home, we had made a new friend — and learned to hold on tighter!","explanation_cn":"课文说 it had already landed in a far field。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"What had grown strong by the time they reached the park?","options":["The crowd","The sun","The wind","The rain"],"answer_index":2,"audio":"By the time we reached the park, the wind had already grown strong. We had been looking forward to flying our new kite all week. Leo had built it himself, and he had been painting it for two days. Before we even started, the wind had pulled the kite from his hands. It had been flying high for only a minute when the string broke. The kite had disappeared over the trees before we could catch it. We searched everywhere, but it had already landed in a far field. A little girl had found it and had been holding it carefully. She had been waiting for someone to come back for it. By the time we got home, we had made a new friend — and learned to hold on tighter!","explanation_cn":"课文说 the wind had already grown strong。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l86',10,NULL,'choice','{"stem":"Who had been holding the kite carefully?","options":["A little girl","A teacher","A police officer","Leo"],"answer_index":0,"audio":"By the time we reached the park, the wind had already grown strong. We had been looking forward to flying our new kite all week. Leo had built it himself, and he had been painting it for two days. Before we even started, the wind had pulled the kite from his hands. It had been flying high for only a minute when the string broke. The kite had disappeared over the trees before we could catch it. We searched everywhere, but it had already landed in a far field. A little girl had found it and had been holding it carefully. She had been waiting for someone to come back for it. By the time we got home, we had made a new friend — and learned to hold on tighter!","explanation_cn":"课文说 A little girl… had been holding it carefully。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l87',2,11,87,'What Did She Say?','她说了什么?','复习 KS15/39/63 间接引语(方案B换情节包):直接引语变间接引语时的时态后移、say that / tell sb that 的区别、一般疑问用 ask if/whether、特殊疑问用 ask + 疑问词并改陈述语序;附语域注(口语转述当下仍成立的事时态可不后移)','昨天,一位记者就那场大赛采访了我们的教练。她问他球队是怎么备战的。他说他们那一个月一直在刻苦训练。他告诉她,队员们都准备好了,信心十足。记者问明星球员会不会上场。他说她状态很好,肯定会打。她问比赛几点开始。他告诉她当晚七点开赛。他还补充说,希望球迷们都来加油助威。后来,记者写道,这位教练听上去非常乐观。','{"q":"Listen and answer — Who did the reporter interview?","options":["The team''s coach","A star player","A fan in the crowd","The referee"],"answer_index":0}'::jsonb,'{"title":"复习 KS15/39/63 间接引语","intro":"把别人的话转述出来,就是间接引语。要点:①时态后移——主句是过去时(said/told/asked)时,从句里的现在→过去、现在完成→过去完成、will→would(He said they had been training / the players were ready);②say 与 tell 的区别——tell 后面要跟人(told her that…),say 后面不直接跟人(said that…);③一般疑问的转述用 ask if / whether(asked whether she would play);④特殊疑问的转述用 ask + 疑问词,且从句改成陈述语序、不倒装(asked when the game would start,不是 when would the game start)。","table":{"headers":["转述方式","例子"],"rows":[["say that / tell sb that","He said that… / He told her that…"],["时态后移","\"They are ready\" → He said they were ready."],["一般疑问 ask if/whether","\"Will she play?\" → She asked whether she would play."],["特殊疑问 ask + 疑问词(陈述语序)","\"When does it start?\" → She asked when it started."]]},"specialRules":[{"rule":"美语“足球场”常说 field(英式 pitch);“电影”说 movie(英式 film)。本课已按美语写。","mark":"field / movie"},{"rule":"tell 后面必须跟人(told her that…),say 后面不直接跟人(said that…);特殊疑问转述后从句用陈述语序,不倒装。","mark":"say/tell + 语序"},{"rule":"语域注:口语里转述“当下仍成立”的事,时态可以不后移(He said the team is ready 也自然);正式书面则一般后移(was ready)。本课按正式书面的后移作答。","mark":"语域"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l87',1,NULL,'Yesterday a reporter asked our coach about the big game. She asked him how the team had prepared.','昨天,一位记者就那场大赛采访了我们的教练。她问他球队是怎么备战的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l87',2,NULL,'He said that they had been training hard all month. He told her that the players were ready and confident.','他说他们那一个月一直在刻苦训练。他告诉她,队员们都准备好了,信心十足。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l87',3,NULL,'The reporter asked whether the star player would join the match. He said that she was feeling great and would definitely play.','记者问明星球员会不会上场。他说她状态很好,肯定会打。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l87',4,NULL,'She asked when the game would start. He told her that it would begin at seven that evening.','她问比赛几点开始。他告诉她当晚七点开赛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l87',5,NULL,'He added that he hoped the fans would come and cheer. Later, the reporter wrote that the coach sounded very positive.','他还补充说,希望球迷们都来加油助威。后来,记者写道,这位教练听上去非常乐观。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
