INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l87','ask about','',NULL,'/æsk əˈbaʊt/','A reporter asked our coach about the big game.','一位记者就大赛采访了我们的教练。','She asked me about my new job.','她问起我的新工作。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l87','get ready','',NULL,'/ɡet ˈredi/','The players got ready for the big game.','队员们为大赛做好了准备。','Get ready — the show is about to start.','准备好——演出就要开始了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l87','the big game','',NULL,'/ðə bɪɡ ɡeɪm/','A reporter asked the coach about the big game.','记者向教练问起那场大赛。','Everyone is excited about the big game tonight.','大家都为今晚的大赛感到兴奋。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l87','come and cheer','',NULL,'/kʌm ənd tʃɪr/','He hoped the fans would come and cheer.','他希望球迷们都来加油。','Come and cheer for our team on Saturday!','周六来为我们队加油吧!') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp1','choice','{"stem":"\"He said that they ___ hard all month.\"(直接引语 have been training,转述后时态后移)","options":["have been training","are training","had been training","train"],"answer_index":2,"stem_cn":"他说他们那一个月一直在刻苦训练。","explanation_cn":"主句是过去时(said),转述时时态后移:现在完成进行 have been training → 过去完成进行 had been training。✓ He said that they had been training hard. ✗ have been training:未后移;✗ are training:未后移;✗ train:未后移。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp1','choice','{"stem":"\"He told her that the players ___ ready.\"(直接引语 are ready,转述后时态后移)","options":["will be","were","are","have been"],"answer_index":1,"stem_cn":"他告诉她队员们都准备好了。","explanation_cn":"主句是过去时(told),转述时 are → were(时态后移)。✓ He told her that the players were ready. ✗ are:未后移;✗ will be:未后移;✗ have been:与直接引语 are 不对应。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp1','choice','{"stem":"\"The reporter wrote that the coach ___ very positive.\"(直接引语 sounds,转述后时态后移)","options":["has sounded","sounds","will sound","sounded"],"answer_index":3,"stem_cn":"记者写道,这位教练听上去非常乐观。","explanation_cn":"主句是过去时(wrote),转述时 sounds → sounded(时态后移)。✓ The reporter wrote that the coach sounded very positive. ✗ sounds:未后移;✗ will sound:未后移;✗ has sounded:与直接引语 sounds 不对应。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp2','choice','{"stem":"\"He ___ her that it would begin at seven.\"(后面直接跟人 her,用哪个词)","options":["spoke","told","said","talked"],"answer_index":1,"stem_cn":"他告诉她当晚七点开赛。","explanation_cn":"后面直接跟人(her)时,用 tell。✓ He told her that it would begin at seven. ✗ said:后面不直接跟人;✗ spoke:不接 that 从句转述内容;✗ talked:不接 that 从句转述内容。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp2','choice','{"stem":"\"He ___ that they had trained hard.\"(后面不跟人,用哪个词)","options":["spoke","told to","said","told"],"answer_index":2,"stem_cn":"他说他们一直刻苦训练。","explanation_cn":"后面不跟人、直接接 that 从句,用 say。✓ He said that they had trained hard. ✗ told:后面要跟人;✗ told to:错;✗ spoke:不接 that 从句转述内容。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp2','choice','{"stem":"\"He ___ that he hoped the fans would cheer.\"(补充说,用哪个词)","options":["said to","told","spoke to","added"],"answer_index":3,"stem_cn":"他补充说,希望球迷们都来加油。","explanation_cn":"“补充说”用 add(过去式 added),后接 that 从句。✓ He added that he hoped the fans would cheer. ✗ told:后面要跟人;✗ spoke to:后面跟人不跟 that;✗ said to:错搭。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp3','choice','{"stem":"\"The reporter asked ___ the star player would join the match.\"(转述一般疑问)","options":["that","whether","what","how"],"answer_index":1,"stem_cn":"记者问明星球员会不会上场。","explanation_cn":"转述一般疑问(是否),用 whether(或 if)。✓ The reporter asked whether the star player would join. ✗ that:用于陈述内容,不用于疑问;✗ what:引导“什么”;✗ how:引导“如何”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp3','choice','{"stem":"\"She asked ___ the team was ready.\"(转述一般疑问,另一种说法)","options":["that","so","if","what"],"answer_index":2,"stem_cn":"她问球队是否准备好了。","explanation_cn":"转述一般疑问,可用 if(等于 whether)。✓ She asked if the team was ready. ✗ that:不用于疑问;✗ what:引导“什么”;✗ so:不引导疑问。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp3','choice','{"stem":"\"He asked me ___ I had enjoyed the game.\"(转述一般疑问)","options":["whether","which","that","so"],"answer_index":0,"stem_cn":"他问我是否喜欢这场比赛。","explanation_cn":"转述一般疑问(是否),用 whether。✓ He asked me whether I had enjoyed the game. ✗ that:不用于疑问;✗ which:引导“哪一个”;✗ so:不引导疑问。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp4','choice','{"stem":"\"She asked him ___ the team had prepared.\"(用“如何”引导,陈述语序)","options":["if","whether","that","how"],"answer_index":3,"stem_cn":"她问他球队是怎么备战的。","explanation_cn":"转述“如何”这类特殊疑问,用 how,从句用陈述语序。✓ She asked him how the team had prepared. ✗ that:不引导疑问;✗ whether / if:引导“是否”,与“如何”不符。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp4','choice','{"stem":"\"She asked ___ the game would start.\"(用“何时”引导)","options":["whether","if","when","that"],"answer_index":2,"stem_cn":"她问比赛几点开始。","explanation_cn":"转述“何时”这类特殊疑问,用 when。✓ She asked when the game would start. ✗ that:不引导疑问;✗ if / whether:引导“是否”,与“何时”不符。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp4','choice','{"stem":"\"She asked where they ___ every day.\"(特殊疑问转述,陈述语序、不倒装)","options":["trained","did they train","train","do train"],"answer_index":0,"stem_cn":"她问他们每天在哪里训练。","explanation_cn":"特殊疑问转述后,从句用陈述语序、不倒装,且时态后移。✓ She asked where they trained every day. ✗ do train:一般现在且带助动词,应后移;✗ did they train:仍是倒装疑问语序;✗ train:未后移。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp5','choice','{"stem":"\"He said that she ___ definitely play.\"(直接引语 will play,转述后 will 变哪个词)","options":["would to","would","will","shall"],"answer_index":1,"stem_cn":"他说她肯定会上场打。","explanation_cn":"转述时 will → would(时态后移)。✓ He said that she would definitely play. ✗ will:未后移;✗ would to:错;✗ shall:不对应。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp5','choice','{"stem":"\"She asked when the game ___ start.\"(直接引语 will start,转述后 will 变哪个词)","options":["shall","would to","would","will"],"answer_index":2,"stem_cn":"她问比赛几点开始。","explanation_cn":"转述时 will → would(时态后移)。✓ She asked when the game would start. ✗ will:未后移;✗ would to:错;✗ shall:不对应。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp5','choice','{"stem":"\"She asked him how the team ___.\"(直接引语 has prepared,转述后时态后移)","options":["has prepared","prepared","prepares","had prepared"],"answer_index":3,"stem_cn":"她问他球队是怎么备战的。","explanation_cn":"转述时现在完成 has prepared → 过去完成 had prepared(时态后移)。✓ She asked how the team had prepared. ✗ has prepared:未后移;✗ prepared:与直接引语 has prepared 不对应;✗ prepares:未后移。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp6','choice','{"stem":"\"A ___ asked the coach about the big game.\"(记者用哪个词)","options":["reporter","farmer","doctor","driver"],"answer_index":0,"stem_cn":"一位记者就大赛采访了教练。","explanation_cn":"采访、写报道的“记者”是 reporter。✓ A reporter asked the coach. ✗ farmer:农民;✗ driver:司机;✗ doctor:医生。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp6','choice','{"stem":"\"He said the players were ready and ___.\"(自信的用哪个词)","options":["afraid","confident","hungry","sleepy"],"answer_index":1,"stem_cn":"他说队员们都准备好了,信心十足。","explanation_cn":"“自信的”是 confident。✓ ready and confident. ✗ hungry:饿的;✗ sleepy:困的;✗ afraid:害怕的。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',5,'am2_l87_gp6','choice','{"stem":"\"He hoped the fans would come and ___.\"(欢呼、加油用哪个词)","options":["cheer","sleep","leave","cry"],"answer_index":0,"stem_cn":"他希望球迷们都来加油助威。","explanation_cn":"“欢呼、加油”是 cheer。✓ come and cheer. ✗ cry:哭;✗ sleep:睡觉;✗ leave:离开。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"美语里\"足球场\"说:","options":["court","ground","field","pitch"],"answer_index":2,"explanation_cn":"美语“(足球)球场”说 field;英式说 pitch。✓ The team trained on the field. 球队在球场上训练。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"美语里\"电影\"说:","options":["picture-play","cinema-show","film","movie"],"answer_index":3,"explanation_cn":"美语“电影”说 movie;英式说 film。✓ They watched a movie after the game. 赛后他们看了场电影。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"reporter 的意思是:","options":["队长","球迷","记者","教练"],"answer_index":2,"explanation_cn":"reporter = 记者。✓ a reporter asked our coach 一位记者采访了教练。\n顺带记:教练 = coach;球迷 = fan;队长 = captain."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"confident 的意思是:","options":["生气的","疲惫的","害怕的","自信的"],"answer_index":3,"explanation_cn":"confident = 自信的。✓ ready and confident 准备好、信心十足。\n顺带记:害怕的 = afraid;疲惫的 = tired;生气的 = angry."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"cheer 的意思是:","options":["离开","欢呼,加油","哭泣","睡觉"],"answer_index":1,"explanation_cn":"cheer = 欢呼、加油。✓ come and cheer 来加油助威。\n顺带记:哭泣 = cry;离开 = leave;睡觉 = sleep."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',6,NULL,'choice','{"stem":"prepare 的意思是:","options":["隐藏","出售","忘记","准备,备战"],"answer_index":3,"explanation_cn":"prepare = 准备、备战。✓ how the team had prepared 球队是怎么备战的。\n顺带记:忘记 = forget;出售 = sell;隐藏 = hide."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',7,NULL,'cloze','{"stem":"第 1 空","context":"Yesterday a reporter asked our coach ___1___ the team had prepared. He ___2___ that they had trained hard. He told her that the players ___3___ ready. She asked ___4___ the game would start.","blank_no":1,"options":["how","that","if","whether"],"answer_index":0,"explanation_cn":"转述“如何”用 how,从句用陈述语序。✓ …asked our coach how the team had prepared.\n✗ that:不引导疑问;✗ if / whether:引导“是否”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',7,NULL,'cloze','{"stem":"第 2 空","context":"Yesterday a reporter asked our coach ___1___ the team had prepared. He ___2___ that they had trained hard. He told her that the players ___3___ ready. She asked ___4___ the game would start.","blank_no":2,"options":["said","told","spoke","talked"],"answer_index":0,"explanation_cn":"后面不跟人、直接接 that 从句,用 say。✓ He said that they had trained hard.\n✗ told:后面要跟人;✗ spoke / talked:不接 that 从句转述内容。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',7,NULL,'cloze','{"stem":"第 3 空","context":"Yesterday a reporter asked our coach ___1___ the team had prepared. He ___2___ that they had trained hard. He told her that the players ___3___ ready. She asked ___4___ the game would start.","blank_no":3,"options":["were","are","will be","have been"],"answer_index":0,"explanation_cn":"转述时 are → were(时态后移)。✓ He told her that the players were ready.\n✗ are:未后移;✗ will be:未后移;✗ have been:不对应。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',7,NULL,'cloze','{"stem":"第 4 空","context":"Yesterday a reporter asked our coach ___1___ the team had prepared. He ___2___ that they had trained hard. He told her that the players ___3___ ready. She asked ___4___ the game would start.","blank_no":4,"options":["when","that","so","which"],"answer_index":0,"explanation_cn":"转述“何时”用 when。✓ She asked when the game would start.\n✗ that:不引导疑问;✗ so / which:与“何时”不符。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',8,NULL,'choice','{"stem":"Who did the reporter interview about the big game?","options":["A star player","The referee","A fan","The team''s coach"],"answer_index":3,"explanation_cn":"课文说 a reporter asked our coach about the big game——记者采访的是教练。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',8,NULL,'choice','{"stem":"What did the coach say about the players?","options":["They were tired and nervous","They had already lost","They were ready and confident","They needed more time"],"answer_index":2,"explanation_cn":"课文说 He told her that the players were ready and confident。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',8,NULL,'choice','{"stem":"When would the game start?","options":["At nine o''clock","At seven that evening","The next morning","At noon"],"answer_index":1,"explanation_cn":"课文说 He told her that it would begin at seven that evening。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',9,NULL,'choice','{"stem":"你想说\"他说他们那个月一直在刻苦训练\"(间接引语时态后移):","options":["He said that they train hard all month.","He said that they had been training hard all month.","He said that they are training hard all month.","He said that they have been training hard all month."],"answer_index":1,"explanation_cn":"转述时时态后移:现在完成进行 → 过去完成进行。✓ He said that they had been training hard all month. 场合:把别人说的话正式书面转述出来。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',9,NULL,'choice','{"stem":"你想说\"记者问明星球员是否会参赛\"(一般疑问用 whether/if):","options":["The reporter asked that the star player would join the match.","The reporter asked the star player would join the match?","The reporter asked whether the star player would join the match.","The reporter asked will the star player join the match."],"answer_index":2,"explanation_cn":"转述一般疑问用 whether/if,will 后移为 would。✓ The reporter asked whether the star player would join the match. 场合:转述一个“是否”的问题。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',9,NULL,'choice','{"stem":"你想说\"她问比赛什么时候开始\"(特殊疑问,陈述语序、不倒装):","options":["She asked when the game would start.","She asked when will the game start.","She asked when would the game start.","She asked when does the game start."],"answer_index":0,"explanation_cn":"转述特殊疑问用疑问词 + 陈述语序,不倒装。✓ She asked when the game would start. 场合:转述一个“何时”的问题。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"reporter 的意思是:","options":["记者","球迷","教练","队长"],"answer_index":0,"explanation_cn":"reporter = 记者。✓ a reporter asked our coach 一位记者采访了教练。\n顺带记:教练 = coach;球迷 = fan;队长 = captain."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"cheer 的意思是:","options":["离开","哭泣","欢呼,加油","睡觉"],"answer_index":2,"explanation_cn":"cheer = 欢呼、加油。✓ come and cheer 来加油助威。\n顺带记:哭泣 = cry;离开 = leave;睡觉 = sleep."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"\"He ___ her that the players were ready.\"(后面直接跟人 her)","options":["spoke","told","talked","said"],"answer_index":1,"stem_cn":"他告诉她队员们都准备好了。","explanation_cn":"后面直接跟人(her)时,用 tell。✓ He told her that the players were ready.\n✗ said:后面不直接跟人;✗ spoke / talked:不接 that 从句转述内容。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"\"The reporter asked ___ the star player would play.\"(转述一般疑问)","options":["whether","how","what","that"],"answer_index":0,"stem_cn":"记者问明星球员会不会上场。","explanation_cn":"转述一般疑问(是否)用 whether(或 if)。✓ The reporter asked whether the star player would play.\n✗ that:不引导疑问;✗ what:引导“什么”;✗ how:引导“如何”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"\"the big game\" 的意思是:","options":["大型玩具","那场大赛(重要比赛)","很大的游戏机","宽阔的场地"],"answer_index":1,"explanation_cn":"the big game = 那场大赛、那场重要比赛。✓ asked the coach about the big game。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"\"come and cheer\" 的意思是:","options":["来变高兴","来道歉","过来又走了","来加油、欢呼助威"],"answer_index":3,"explanation_cn":"come and cheer = 来加油、欢呼助威(cheer = 欢呼、加油)。✓ He hoped the fans would come and cheer。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"What did the reporter ask the coach about?","options":["The big game","The weather","His salary","A new stadium"],"answer_index":0,"passage":"Yesterday a reporter asked our coach about the big game. She asked him how the team had prepared. He said that they had been training hard all month. He told her that the players were ready and confident. The reporter asked whether the star player would join the match. He said that she was feeling great and would definitely play. She asked when the game would start. He told her that it would begin at seven that evening. He added that he hoped the fans would come and cheer. Later, the reporter wrote that the coach sounded very positive.","explanation_cn":"课文说 a reporter asked our coach about the big game。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"What did the coach hope the fans would do?","options":["Be quiet","Bring food","Stay at home","Come and cheer"],"answer_index":3,"passage":"Yesterday a reporter asked our coach about the big game. She asked him how the team had prepared. He said that they had been training hard all month. He told her that the players were ready and confident. The reporter asked whether the star player would join the match. He said that she was feeling great and would definitely play. She asked when the game would start. He told her that it would begin at seven that evening. He added that he hoped the fans would come and cheer. Later, the reporter wrote that the coach sounded very positive.","explanation_cn":"课文说 he hoped the fans would come and cheer。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"Who did the reporter talk to?","options":["A referee","The coach","A fan","A star player"],"answer_index":1,"audio":"Yesterday a reporter asked our coach about the big game. She asked him how the team had prepared. He said that they had been training hard all month. He told her that the players were ready and confident. The reporter asked whether the star player would join the match. He said that she was feeling great and would definitely play. She asked when the game would start. He told her that it would begin at seven that evening. He added that he hoped the fans would come and cheer. Later, the reporter wrote that the coach sounded very positive.","explanation_cn":"课文说 a reporter asked our coach——记者采访的是教练。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l87',10,NULL,'choice','{"stem":"When would the game start?","options":["At nine","At noon","The next day","At seven that evening"],"answer_index":3,"audio":"Yesterday a reporter asked our coach about the big game. She asked him how the team had prepared. He said that they had been training hard all month. He told her that the players were ready and confident. The reporter asked whether the star player would join the match. He said that she was feeling great and would definitely play. She asked when the game would start. He told her that it would begin at seven that evening. He added that he hoped the fans would come and cheer. Later, the reporter wrote that the coach sounded very positive.","explanation_cn":"课文说 it would begin at seven that evening。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l88',2,11,88,'Lost and Found','失物招领','复习 KS16/40/64 条件句 if(方案B换情节包):真实条件(if + 现在时, will/should do)、与现在事实相反的非真实条件(if + 过去式, would do;if I were you)、与过去事实相反的非真实条件(if + had done, would have done),以及 if 条件从句里不用 will、用现在时表将来的规则','如果你在学校丢了东西,应该去查一下失物招领箱。上周,要不是我去查了一下,我的背包就永远找不回来了。“如果我是你,”朋友说,“我会把名字写在每样东西上。”要是每个人都给自己的东西贴上标签,那箱子就不会这么满了。“要是你找到我的包,请给我打电话,”我对办公室说。当初我要是再细心点,这事就不会发生了。“它一旦出现,我们就通知你,”办公室的职员说。你只要礼貌地问,大家通常都会帮你。第二天——说来你可能不信——我的包就在我课桌上!以后我要是再丢东西,我就完全知道该怎么办了。','{"q":"Listen and answer — What should you do if you lose something at school?","options":["Check the lost-and-found box","Go straight home","Buy a new one","Tell no one"],"answer_index":0}'::jsonb,'{"title":"复习 KS16/40/64 条件句 if","intro":"if 条件句分两大类:①真实条件——可能发生的事,if + 一般现在时,主句用 will / should / 祈使句(If you lose something, you should check the box);②非真实条件(虚拟)——与事实相反的假设。又分两种:与现在相反,if + 过去式,主句 would do,be 一律用 were(If I were you, I would label everything);与过去相反,if + had done,主句 would have done(If I hadn''t checked it, I would have lost my bag)。要点:if 条件从句里不用 will,要用一般现在时表将来(If it turns up, we will let you know)。","table":{"headers":["类型","例子"],"rows":[["真实条件(if + 现在, will/should)","If you lose it, you should check the box."],["与现在相反(if + 过去式, would do)","If I were you, I would label everything."],["与过去相反(if + had done, would have done)","If I hadn''t checked, I would have lost it."],["从句用现在表将来","If it turns up, we will let you know."]]},"specialRules":[{"rule":"美语“橡皮擦”说 eraser(英式 rubber);“失物招领处”说 lost-and-found(英式 lost property)。本课已按美语写。","mark":"eraser / lost-and-found"},{"rule":"与现在相反的假设,be 动词一律用 were(即使主语是 I/he/she);与过去相反用 if + had done → would have done;真实条件的 if 从句里不用 will。","mark":"if 用法"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l88',1,NULL,'If you lose something at school, you should check the lost-and-found box. Last week, if I hadn''t checked it, I would have lost my backpack forever.','如果你在学校丢了东西,应该去查一下失物招领箱。上周,要不是我去查了一下,我的背包就永远找不回来了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l88',2,NULL,'"If I were you," my friend said, "I would put my name on everything." If everyone labeled their things, the box wouldn''t be so full.','“如果我是你,”朋友说,“我会把名字写在每样东西上。”要是每个人都给自己的东西贴上标签,那箱子就不会这么满了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l88',3,NULL,'"If you find my bag," I told the office, "please call me." If I had been more careful, this wouldn''t have happened.','“要是你找到我的包,请给我打电话,”我对办公室说。当初我要是再细心点,这事就不会发生了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l88',4,NULL,'"If it turns up, we will let you know," the secretary said. If you ask politely, people usually help you.','“它一旦出现,我们就通知你,”办公室的职员说。你只要礼貌地问,大家通常都会帮你。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l88',5,NULL,'The next day, if you can believe it, my bag was on my desk! If I ever lose something again, I will know exactly what to do.','第二天——说来你可能不信——我的包就在我课桌上!以后我要是再丢东西,我就完全知道该怎么办了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
