INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l88','believe','/bɪˈliːv/','v','相信','if you can believe it') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
