INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l88','sneakers','trainers','运动鞋;美语 sneakers,英式 trainers') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l88','lost and found','',NULL,'/lɔːst ənd faʊnd/','You should check the lost-and-found box.','你应该去查失物招领箱。','I found my hat at the lost and found.','我在失物招领处找到了我的帽子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l88','turn up','',NULL,'/tɜːrn ʌp/','If it turns up, we will let you know.','它一旦出现,我们就通知你。','My keys finally turned up under the sofa.','我的钥匙终于在沙发底下找到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l88','if I were you','',NULL,'/ɪf aɪ wɜːr ju/','If I were you, I would label everything.','如果我是你,我会给每样东西贴标签。','If I were you, I would call first.','如果我是你,我会先打个电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l88','look for','',NULL,'/lʊk fɔːr/','I would help you look for it.','我会帮你找它。','She is looking for her lost gloves.','她正在找丢失的手套。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp1','choice','{"stem":"\"If you ___ something at school, you should check the lost-and-found box.\"(真实条件:if 从句用现在时)","options":["will lose","lost","lose","would lose"],"answer_index":2,"stem_cn":"如果你在学校丢了东西,应该去查失物招领箱。","explanation_cn":"真实条件(可能发生的事),if 从句用一般现在时。✓ If you lose something, you should check the box. ✗ will lose:if 从句里不用 will;✗ lost:这里不是虚拟;✗ would lose:这里不是虚拟。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp1','choice','{"stem":"\"If you ask politely, people usually ___ you.\"(真实条件:主句用一般现在)","options":["help","would help","helped","had helped"],"answer_index":0,"stem_cn":"你只要礼貌地问,大家通常都会帮你。","explanation_cn":"真实条件,主句说“通常会怎样”,用一般现在时。✓ If you ask politely, people usually help you. ✗ helped:一般过去,与 usually 不符;✗ would help:这里不是虚拟;✗ had helped:过去完成不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp1','choice','{"stem":"\"If it turns up, we ___ you know.\"(真实条件:主句用 will)","options":["let","would let","would have let","will let"],"answer_index":3,"stem_cn":"它一旦出现,我们就通知你。","explanation_cn":"真实条件,主句表将来,用 will + 原形。✓ If it turns up, we will let you know. ✗ would let:这里不是虚拟;✗ let:缺 will,不表将来;✗ would have let:与过去相反的形式,不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp2','choice','{"stem":"\"If everyone labeled their things, the box ___ so full.\"(与现在相反:主句用 would)","options":["hadn''t been","won''t be","wouldn''t be","isn''t"],"answer_index":2,"stem_cn":"要是每个人都给东西贴标签,箱子就不会这么满。","explanation_cn":"与现在事实相反的假设(其实并非人人贴标签),主句用 would。✓ If everyone labeled their things, the box wouldn''t be so full. ✗ won''t be:真实条件的形式,这里是虚拟;✗ isn''t:一般现在;✗ hadn''t been:与过去相反的形式,不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp2','choice','{"stem":"\"''If I ___ you, I would put my name on everything,'' my friend said.\"(与现在事实相反的假设,be 动词该用哪个形式)","options":["was","am","will be","were"],"answer_index":3,"stem_cn":"“如果我是你,我会把名字写在每样东西上。”","explanation_cn":"与现在相反的假设里,be 动词一律用 were(即使主语是 I)。✓ If I were you, I would put my name on everything. ✗ am:真实语气;✗ was:虚拟里 be 用 were 不用 was;✗ will be:将来,不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp2','choice','{"stem":"\"If I had more time, I ___ help you look for it.\"(与现在事实相反的假设,主句该用哪个词)","options":["would","am","will","would have"],"answer_index":0,"stem_cn":"要是我有更多时间,我会帮你找。","explanation_cn":"与现在相反的假设,主句用 would + 原形。✓ If I had more time, I would help you. ✗ will:真实条件形式;✗ would have:与过去相反的形式;✗ am:一般现在。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp3','choice','{"stem":"\"Last week, if I hadn''t checked it, I ___ my backpack forever.\"(与过去相反:主句 would have done)","options":["will lose","would have lost","would lose","lost"],"answer_index":1,"stem_cn":"上周要不是我查了一下,我的背包就永远找不回来了。","explanation_cn":"与过去相反的假设,主句用 would have + 过去分词。✓ If I hadn''t checked it, I would have lost my backpack. ✗ would lose:与现在相反的形式;✗ will lose:真实条件形式;✗ lost:一般过去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp3','choice','{"stem":"\"If I ___ more careful, this wouldn''t have happened.\"(与过去相反:if 从句用 had done)","options":["am","were","was","had been"],"answer_index":3,"stem_cn":"当初我要是再细心点,这事就不会发生。","explanation_cn":"与过去相反的假设,if 从句用 had + 过去分词。✓ If I had been more careful, this wouldn''t have happened. ✗ was:一般过去;✗ were:与现在相反的形式;✗ am:一般现在。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp3','choice','{"stem":"\"If she had labeled her bag, it ___ so easily.\"(与过去相反:主句 wouldn''t have done)","options":["isn''t lost","wouldn''t have been lost","wouldn''t be lost","won''t be lost"],"answer_index":1,"stem_cn":"要是她给包贴了标签,它就不会这么容易弄丢了。","explanation_cn":"与过去相反的假设,主句用 would have + 过去分词(此处为被动 have been + 过去分词)。✓ If she had labeled her bag, it wouldn''t have been lost so easily. ✗ wouldn''t be lost:与现在相反的形式;✗ won''t be lost:真实条件形式;✗ isn''t lost:一般现在。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp4','choice','{"stem":"\"If it ___ up, we will let you know.\"(条件从句用现在时,不用 will)","options":["turned","would turn","will turn","turns"],"answer_index":3,"stem_cn":"它一旦出现,我们就通知你。","explanation_cn":"if 条件从句里用一般现在时表将来,不用 will。✓ If it turns up, we will let you know. ✗ will turn:从句里不用 will;✗ would turn:虚拟形式;✗ turned:一般过去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp4','choice','{"stem":"\"If you ___ politely, people help you.\"(条件从句用一般现在)","options":["asked","would ask","ask","will ask"],"answer_index":2,"stem_cn":"你只要礼貌地问,大家就会帮你。","explanation_cn":"if 条件从句里用一般现在时。✓ If you ask politely, people help you. ✗ will ask:从句里不用 will;✗ would ask:虚拟形式;✗ asked:一般过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp4','choice','{"stem":"\"If I ever ___ something again, I will know what to do.\"(条件从句用现在时表将来)","options":["would lose","lose","lost","will lose"],"answer_index":1,"stem_cn":"以后我要是再丢东西,就知道该怎么办了。","explanation_cn":"if 条件从句里用一般现在时表将来。✓ If I ever lose something again, I will know what to do. ✗ will lose:从句里不用 will;✗ would lose:虚拟形式;✗ lost:一般过去。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp5','choice','{"stem":"\"If you find my bag, please ___ me.\"(真实条件里的请求,用祈使)","options":["called","will called","would call","call"],"answer_index":3,"stem_cn":"要是你找到我的包,请给我打电话。","explanation_cn":"真实条件里提出请求,用祈使句(动词原形开头)。✓ If you find my bag, please call me. ✗ called:一般过去;✗ would call:虚拟形式;✗ will called:错形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp5','choice','{"stem":"\"If I had known, I ___ come earlier.\"(与过去相反)","options":["will have","would have","would","had"],"answer_index":1,"stem_cn":"要是我早知道,我就早点来了。","explanation_cn":"与过去相反的假设,主句用 would have + 过去分词。✓ If I had known, I would have come earlier. ✗ would:与现在相反的形式;✗ will have:真实语气;✗ had:不构成主句。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp5','choice','{"stem":"\"If it rains tomorrow, we ___ stay inside.\"(真实条件·说将来)","options":["will","would have","would","are"],"answer_index":0,"stem_cn":"要是明天下雨,我们就待在室内。","explanation_cn":"真实条件说将来,主句用 will + 原形。✓ If it rains tomorrow, we will stay inside. ✗ would:虚拟形式;✗ would have:与过去相反的形式;✗ are:缺 will。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp6','choice','{"stem":"\"I keep my books in my ___.\"(背包用哪个词)","options":["river","backpack","garden","kitchen"],"answer_index":1,"stem_cn":"我把书放在背包里。","explanation_cn":"装书本的“背包”是 backpack。✓ keep my books in my backpack. ✗ kitchen:厨房;✗ garden:花园;✗ river:河。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp6','choice','{"stem":"\"If you ___ your things with your name, you won''t lose them.\"(贴标签、标注用哪个词)","options":["sleep","cook","label","sing"],"answer_index":2,"stem_cn":"要是你给东西贴上写着名字的标签,就不会丢了。","explanation_cn":"“贴标签、标注”是 label。✓ label your things with your name. ✗ cook:做饭;✗ sing:唱歌;✗ sleep:睡觉。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',5,'am2_l88_gp6','choice','{"stem":"\"''If it turns up, we will call you,'' the ___ said.\"(办公室职员用哪个词)","options":["pilot","secretary","farmer","singer"],"answer_index":1,"stem_cn":"“它一旦出现,我们就打电话给你,”办公室职员说。","explanation_cn":"办公室里的“职员、秘书”是 secretary。✓ the secretary said. ✗ farmer:农民;✗ pilot:飞行员;✗ singer:歌手。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"美语里\"橡皮擦\"说:","options":["cleaner","rubber","wiper","eraser"],"answer_index":3,"explanation_cn":"美语“橡皮擦”说 eraser;英式说 rubber。✓ Can I borrow your eraser? 能借下你的橡皮吗?"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"美语里\"背包、双肩包\"常说:","options":["carry-bag","backpack","rucksack","satchel"],"answer_index":1,"explanation_cn":"美语“背包、双肩包”常说 backpack;英式说 rucksack。✓ She carried a heavy backpack. 她背着一个沉重的背包。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"backpack 的意思是:","options":["鞋子","手表","背包","帽子"],"answer_index":2,"explanation_cn":"backpack = 背包、双肩包。✓ my backpack 我的背包。\n顺带记:帽子 = hat;鞋子 = shoes;手表 = watch."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"forever 的意思是:","options":["立刻","从不","有时","永远"],"answer_index":3,"explanation_cn":"forever = 永远。✓ lost forever 永远地丢失了。\n顺带记:从不 = never;有时 = sometimes;立刻 = at once."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"politely 的意思是:","options":["有礼貌地","快速地","生气地","大声地"],"answer_index":0,"explanation_cn":"politely = 有礼貌地。✓ if you ask politely 你礼貌地问的话。\n顺带记:大声地 = loudly;生气地 = angrily;快速地 = quickly."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',6,NULL,'choice','{"stem":"exactly 的意思是:","options":["错误地","缓慢地","大概地","确切地,正是"],"answer_index":3,"explanation_cn":"exactly = 确切地、正是。✓ know exactly what to do 确切地知道该怎么做。\n顺带记:大概地 = roughly;错误地 = wrongly;缓慢地 = slowly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',7,NULL,'cloze','{"stem":"第 1 空","context":"If you ___1___ something at school, check the lost-and-found box. Last week, if I ___2___ checked it, I would have lost my backpack. \"If I ___3___ you, I would label everything,\" my friend said. If it ___4___ up, they will call you.","blank_no":1,"options":["lose","will lose","lost","would lose"],"answer_index":0,"explanation_cn":"真实条件,if 从句用一般现在时。✓ If you lose something at school, check the box.\n✗ will lose:从句里不用 will;✗ lost / would lose:这里不是虚拟。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',7,NULL,'cloze','{"stem":"第 2 空","context":"If you ___1___ something at school, check the lost-and-found box. Last week, if I ___2___ checked it, I would have lost my backpack. \"If I ___3___ you, I would label everything,\" my friend said. If it ___4___ up, they will call you.","blank_no":2,"options":["hadn''t","didn''t","don''t","wouldn''t"],"answer_index":0,"explanation_cn":"与过去相反的假设,if 从句用 had(此处否定 hadn''t)+ 过去分词。✓ If I hadn''t checked it, I would have lost my backpack.\n✗ didn''t:一般过去;✗ don''t:一般现在;✗ wouldn''t:不构成 if 从句。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',7,NULL,'cloze','{"stem":"第 3 空","context":"If you ___1___ something at school, check the lost-and-found box. Last week, if I ___2___ checked it, I would have lost my backpack. \"If I ___3___ you, I would label everything,\" my friend said. If it ___4___ up, they will call you.","blank_no":3,"options":["were","am","was","will be"],"answer_index":0,"explanation_cn":"与现在相反的假设里,be 用 were。✓ If I were you, I would label everything.\n✗ am:真实语气;✗ was:虚拟里用 were;✗ will be:将来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',7,NULL,'cloze','{"stem":"第 4 空","context":"If you ___1___ something at school, check the lost-and-found box. Last week, if I ___2___ checked it, I would have lost my backpack. \"If I ___3___ you, I would label everything,\" my friend said. If it ___4___ up, they will call you.","blank_no":4,"options":["turns","will turn","would turn","turned"],"answer_index":0,"explanation_cn":"if 条件从句里用现在时表将来。✓ If it turns up, they will call you.\n✗ will turn:从句里不用 will;✗ would turn:虚拟形式;✗ turned:一般过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',8,NULL,'choice','{"stem":"What should you do if you lose something at school?","options":["Go straight home","Buy a new one","Say nothing","Check the lost-and-found box"],"answer_index":3,"explanation_cn":"课文说 If you lose something at school, you should check the lost-and-found box。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',8,NULL,'choice','{"stem":"What did the friend suggest?","options":["Put your name on everything","Never bring a bag","Lock everything away","Ask the teacher"],"answer_index":0,"explanation_cn":"课文说 \"If I were you,\" my friend said, \"I would put my name on everything.\""}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',8,NULL,'choice','{"stem":"Where was the backpack the next day?","options":["In the office","On the writer''s desk","In a far field","At home"],"answer_index":1,"explanation_cn":"课文说 The next day… my bag was on my desk!"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',9,NULL,'choice','{"stem":"你想说\"如果你在学校丢了东西,就去查失物招领箱\"(真实条件:if + 现在时,主句用祈使):","options":["If you will lose something at school, check the lost-and-found box.","If you lost something at school, check the lost-and-found box.","If you would lose something at school, check the lost-and-found box.","If you lose something at school, check the lost-and-found box."],"answer_index":3,"explanation_cn":"真实条件,if 从句用现在时,主句用祈使句。✓ If you lose something at school, check the lost-and-found box. 场合:给出一条“如果……就……”的实用建议。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',9,NULL,'choice','{"stem":"你想说\"如果我是你,我会把名字写在所有东西上\"(与现在相反:if I were you + would):","options":["If I were you, I will put my name on everything.","If I were you, I would put my name on everything.","If I was you, I will put my name on everything.","If I am you, I would put my name on everything."],"answer_index":1,"explanation_cn":"与现在相反的假设,if I were you + would do。✓ If I were you, I would put my name on everything. 场合:给别人提建议“换作我会……”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',9,NULL,'choice','{"stem":"你想说\"上周要不是我查了一下,背包就永远找不回来了\"(与过去相反:if had done, would have done):","options":["If I hadn''t checked it, I would have lost my backpack forever.","If I don''t check it, I will lose my backpack forever.","If I didn''t check it, I would lose my backpack forever.","If I hadn''t checked it, I would lose my backpack forever."],"answer_index":0,"explanation_cn":"与过去相反的假设,if + had done → would have done。✓ If I hadn''t checked it, I would have lost my backpack forever. 场合:设想“当初要不是……,就会……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"backpack 的意思是:","options":["鞋子","帽子","背包","手表"],"answer_index":2,"explanation_cn":"backpack = 背包。✓ my backpack 我的背包。\n顺带记:帽子 = hat;鞋子 = shoes;手表 = watch."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"politely 的意思是:","options":["生气地","快速地","大声地","有礼貌地"],"answer_index":3,"explanation_cn":"politely = 有礼貌地。✓ ask politely 礼貌地问。\n顺带记:大声地 = loudly;生气地 = angrily;快速地 = quickly."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"\"If you ___ something, you should check the lost-and-found box.\"(真实条件)","options":["lost","would lose","lose","will lose"],"answer_index":2,"stem_cn":"如果你丢了东西,应该去查失物招领箱。","explanation_cn":"真实条件,if 从句用一般现在时。✓ If you lose something, you should check the box.\n✗ will lose:从句里不用 will;✗ lost / would lose:这里不是虚拟。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"\"If I ___ you, I would label everything.\"(与现在事实相反的假设,be 动词该用哪个形式)","options":["were","will be","was","am"],"answer_index":0,"stem_cn":"如果我是你,我会给每样东西贴标签。","explanation_cn":"与现在相反的假设里,be 用 were。✓ If I were you, I would label everything.\n✗ am:真实语气;✗ was:虚拟里用 were;✗ will be:将来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"\"lost and found\" 的意思是:","options":["找不见的东西","迷路以后找到","失物招领处","又丢又找不到"],"answer_index":2,"explanation_cn":"lost and found = 失物招领处(放置、领取失物的地方)。✓ check the lost-and-found box。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"\"turn up\" 在这里的意思是:","options":["把音量调大","翻过来","拒绝","(失物)出现、被找到"],"answer_index":3,"explanation_cn":"turn up 在这里 = (失物)出现、被找到。✓ If it turns up, we will let you know。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"What would have happened if the writer hadn''t checked the box?","options":["The friend would have helped","The backpack would have been lost forever","Nothing would have changed","The bag would have been sold"],"answer_index":1,"passage":"If you lose something at school, you should check the lost-and-found box. Last week, if I hadn''t checked it, I would have lost my backpack forever. \"If I were you,\" my friend said, \"I would put my name on everything.\" If everyone labeled their things, the box wouldn''t be so full. \"If you find my bag,\" I told the office, \"please call me.\" If I had been more careful, this wouldn''t have happened. \"If it turns up, we will let you know,\" the secretary said. If you ask politely, people usually help you. The next day, if you can believe it, my bag was on my desk! If I ever lose something again, I will know exactly what to do.","explanation_cn":"课文说 if I hadn''t checked it, I would have lost my backpack forever——即背包本会永远丢失。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"Where was the bag the next day?","options":["At the friend''s house","Still in the box","On the writer''s desk","In a far field"],"answer_index":2,"passage":"If you lose something at school, you should check the lost-and-found box. Last week, if I hadn''t checked it, I would have lost my backpack forever. \"If I were you,\" my friend said, \"I would put my name on everything.\" If everyone labeled their things, the box wouldn''t be so full. \"If you find my bag,\" I told the office, \"please call me.\" If I had been more careful, this wouldn''t have happened. \"If it turns up, we will let you know,\" the secretary said. If you ask politely, people usually help you. The next day, if you can believe it, my bag was on my desk! If I ever lose something again, I will know exactly what to do.","explanation_cn":"课文说 my bag was on my desk!"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"What should you do if you lose something at school?","options":["Check the lost-and-found box","Go home","Buy a new one","Tell no one"],"answer_index":0,"audio":"If you lose something at school, you should check the lost-and-found box. Last week, if I hadn''t checked it, I would have lost my backpack forever. \"If I were you,\" my friend said, \"I would put my name on everything.\" If everyone labeled their things, the box wouldn''t be so full. \"If you find my bag,\" I told the office, \"please call me.\" If I had been more careful, this wouldn''t have happened. \"If it turns up, we will let you know,\" the secretary said. If you ask politely, people usually help you. The next day, if you can believe it, my bag was on my desk! If I ever lose something again, I will know exactly what to do.","explanation_cn":"课文说 you should check the lost-and-found box。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l88',10,NULL,'choice','{"stem":"What did the friend suggest doing?","options":["Never bring a bag","Ask the teacher","Lock the door","Put your name on everything"],"answer_index":3,"audio":"If you lose something at school, you should check the lost-and-found box. Last week, if I hadn''t checked it, I would have lost my backpack forever. \"If I were you,\" my friend said, \"I would put my name on everything.\" If everyone labeled their things, the box wouldn''t be so full. \"If you find my bag,\" I told the office, \"please call me.\" If I had been more careful, this wouldn''t have happened. \"If it turns up, we will let you know,\" the secretary said. If you ask politely, people usually help you. The next day, if you can believe it, my bag was on my desk! If I ever lose something again, I will know exactly what to do.","explanation_cn":"课文说 I would put my name on everything。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
